programs.sol:
"""Approximate a facility-and-capability signal from words and short phrases.

Ease, speed, flexibility, enabling, and useful capabilities are positive; 'easily'
is especially strong. Recognize ability suffixes and a few translations too.
The signal continues onto 'to/of/for/with' in familiar capability constructions.
Negation attenuates selected ease and ability words. Two tokens are remembered; a
new document clears them. Coefficients were estimated from training samples.
This does not explain the component's smaller, idiosyncratic responses to other words.
"""
READS = ()


def words(text):
    return frozenset(text.split())


EASE = words('easy ease convenient conveniently seamless')
ENABLING = words('allow allows allowing enable enables enabling facilitate '
                 'facilitates facilitating facilit')
SUPPORT = words('support supports supporting supported')
OBJECTS = words('you us them me him her it users')

# Named semantic word classes with coarse training-derived estimates.
CLASSES = (
    ('ease adverb', 2.30, words('easily')),
    ('strong ease', 1.70, words('easier intuitive intuitively '
                               'effortlessly seamlessly')),
    ('versatility', 1.55, words('flexibility versatility')),
    ('adaptability', 1.25, words('flexible versatile adaptable customizable scalable')),
    ('ease', 1.05, EASE),
    ('quick action', 1.05, words('quickly rapidly efficiently '
                                'readily instantly swiftly')),
    ('enabling', 1.00, ENABLING),
    ('automation', 0.90, words('automatic automatically automated automation autom')),
    ('ease/speed degree', 0.90, words('easiest faster fastest quicker')),
    ('ease of use and cost', 0.85, words('affordable manageable readable')),
    ('support', 0.70, SUPPORT | words('reliable reliably robust')),
    ('capability', 0.70, words('ability abilities capability capabilities accessible '
                             'accessibility usable portable compatible compatibility')),
    ('direct action', 0.75, words('directly accurately securely')),
    ('simpleness', 0.53, words('simple simply straightforward simplicity')),
    ('speed', 0.55, words('fast quick rapid efficient efficiency')),
    ('provision', 0.55, words('provide provides providing')),
    ('improvement', 0.55, words('improve improves improving improved enhance enhances '
                              'enhanced optimize optimized optimised '
                              'better reduce reduces')),
    ('practical benefit', 0.45, words('useful helpful practical powerful secure ensure '
                                    'ensures correctly freely independently')),
    ('availability', 0.40, words('available availability ready suitable')),
    ('performance', 0.30, words('functionality functional interface interfaces '
                              'features '
                              'handle handles performance performances '
                              'speed high higher')),
    ('offering', 0.32, words('offer offers offering')),
    ('completion', 0.34, words('fully clearly highly immediately direct')),
    ('past enabling', 0.35, words('allowed enabled provided')),
    ('modal verbs', -0.07, words('will would may might')),
    ('requirements and obstacles', -0.10, words('need needs requirement requirements '
                                              'problem challenge challenges hard')),
    ('translated ease', 1.90, words('轻松 便捷 方便 高效 簡単 簡単に удоб легко')),
    ('translated enabling', 1.10, words('实现 支持 快速 灵活 自动 就可以 即可 以便 '
                                      '更好地 permet facile позволя позволяет يمكن')),
    ('translated utility', 0.68, words('提供 进行 智能 能够 功能 便利 直接 可以 可 更 '
                                       '更加 有效 确保 促进 保障 提高 обеспеч эффектив '
                                       'просто 제공')),
)
LEXICON = {w: value for _, value, group in CLASSES for w in group}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, before = carry[1:] if carry and carry[0] == doc else ('', '')
    raw = prefix.token_strings[-1]
    w = raw.strip().lstrip('_-/.').lower()
    p = LEXICON.get(w, 0.0)
    if w == 'capable':
        p = 1.10
    elif w == 'able':
        p = 0.57 if raw[:1].isspace() else 0.34
    elif w in {'ible', 'izable', 'ibility', 'atable', 'itable', 'ifiable'}:
        p = 0.40
    elif w == 'ability' and not raw[:1].isspace():
        p = 0.60
    elif w == 'ly' and not raw[:1].isspace():
        p = 0.10
    elif w in {'allow', 'enable'}:
        p = 0.70
    elif w == 'possible':
        making_possible = prev == 'it' and before in {'make', 'makes', 'made', 'making'}
        p = 1.50 if making_possible else 0.50
    elif w == 'even':
        p = 0.15
    elif w == 'with':
        p = 0.05
    elif w == 'more':
        p = -0.09

    if w in EASE | {'easily', 'easier', 'possible', 'able', 'capable'}:
        if prev in {'not', "n't", "'t", '’t', 'no', 'never'}:
            p *= 0.30
        elif w == 'easily':
            if prev in {'can', 'to'}:
                p += 0.65
            elif prev in {'is', 'are', 'as', 'so'}:
                p -= 0.65
        elif w in {'easy', 'easier'}:
            if prev == 'it':
                p += 1.10
            elif prev == 'for' or prev in ENABLING:
                p += 0.85

    if w == 'to':
        p = 0.01
        if prev in {'how', 'able', 'ability', 'possible', 'impossible', 'easier'}:
            p = 0.85
        elif prev == 'easy':
            p = 1.20
        elif prev in OBJECTS and before in ENABLING:
            p = 1.10
        elif prev in {'way', 'ways', 'learn', 'learning'}:
            p = 0.45
        elif prev in {'unable', 'allowed', 'access', 'ready', 'open'}:
            p = 0.34
        elif prev in {'up', 'hard', 'harder', 'difficult', 'enough'}:
            p = 0.26
    elif w == 'for':
        if prev in {'allow', 'allows', 'allowing'}:
            p = 1.25
        elif prev in SUPPORT | EASE | {'easier'}:
            p = 0.52
    elif w == 'of' and prev in {'capable', 'ease', 'ability', 'capabilities'}:
        p = 0.75 if prev == 'capable' else 0.40
    elif w == 'with' and prev in {'compatible', 'compatibility'}:
        p = 0.55
    elif w in {'can', 'could'}:
        p = 0.32 if prev == 'you' else 0.08
        if prev == 'you' and before == 'so':
            p = 0.60
    return (doc, w, prev), float(p)

programs.haiku:
"""Layer-0 MLP down-projection component 3713: an "again" detector.

Its output is dominated by the word "again": on " again" / " Again" it writes about 11
(the largest response in this site). The same idea in other languages gives a
smaller response: German "wieder" about 2.5, Chinese "再次" / "再度" about 3, Russian
"снова" about 5, Vietnamese "lại" about 1.7. Words that carry a sense of a second time,
a return, or an alternative give about 1: "back", "another", "twice", "once",
"anymore", "repeatedly", "instead", and "against", "together", "alone" and
"indeed". Reflexives (itself, himself, myself, themselves, ...) give about 1.2 to
1.4. Every other token predicts 0.

The program is a token lookup over these word groups, with the activation size per group.
"""

READS = ()

# Activation predicted for each group of words (lower-cased, leading space dropped).
AGAIN = {"again": 11.1}
OTHER_LANGUAGE_AGAIN = {"снова": 5.0, "再次": 3.2, "再度": 3.0, "wieder": 2.5, "lại": 1.7,
                        "また": 0.9, "再": 0.5, "vez": 0.5, "次": 0.6}
RETURN_WORDS = {"back": 1.05, "another": 1.07, "twice": 0.9, "once": 0.9, "anymore": 1.05,
                "repeatedly": 1.3, "instead": 1.08}
REFLEXIVES = {"itself": 1.37, "myself": 1.4, "yourself": 1.16, "himself": 1.22,
              "herself": 1.26, "themselves": 1.16, "ourselves": 1.21}
ALONE_TOGETHER = {"against": 1.25, "together": 1.2, "altogether": 1.06, "alone": 2.0,
                  "indeed": 1.3}

VALUE = {}
for group in (AGAIN, OTHER_LANGUAGE_AGAIN, RETURN_WORDS, REFLEXIVES, ALONE_TOGETHER):
    VALUE.update(group)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return carry, float(VALUE.get(word, 0.0))

programs.luna:
"""A large response to 'again', with weaker repetition and self-reference cues."""

READS = ()

REFLEXIVE_PRONOUNS = frozenset({
    "myself", "yourself", "himself", "herself", "itself", "themselves",
    "ourselves",
})

RELATION_AND_RETURN_WORDS = frozenset({
    "back", "another", "once", "twice", "repeatedly", "anymore",
    "anyway", "instead", "against", "together", "behalf", "altogether",
})

REPEAT_WORDS_IN_OTHER_LANGUAGES = {
    "wieder": 2.6,
    "lại": 1.85,
    "再次": 3.2,
    "再度": 3.1,
    "再": 0.5,
    "一遍": 1.3,
    "回购": 0.85,
    "また": 0.9,
    "vez": 0.5,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()

    if word == "again":
        if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip().casefold()
            if previous == "once":
                return None, 7.7
        return None, 11.0

    if word == "alone":
        return None, 2.1
    if word in REFLEXIVE_PRONOUNS:
        return None, 1.25
    if word in RELATION_AND_RETURN_WORDS:
        return None, 1.15
    if word in REPEAT_WORDS_IN_OTHER_LANGUAGES:
        return None, REPEAT_WORDS_IN_OTHER_LANGUAGES[word]
    if word == "somehow":
        return None, 0.5
    return None, 0.0

programs.sol:
"""Spaces and formatting that introduce content after a full stop or bullet.

Separate spaces are positive after full stops and bullets. Bold, headings, and
space-prefixed split or single Chinese characters strengthen this response.
A digit before the full stop and an early document position give extra boosts.
Tab-plus-space indentation is negative. Most multi-letter words return zero.
The small coefficients below were fitted to these visible text categories.
"""
import math
import unicodedata

READS = ()

# For each visible kind: full-stop baseline, early-document boost,
# numbered-marker boost, and bullet baseline.
BOUNDARIES = {
    'space': (0.59, 2.04, 0.47, 0.74),
    'nonbreaking_space': (0.22, 0.72, 0.26, 0.15),
    'double_space': (0.11, 1.14, 0.35, 0.13),
    'bold': (1.54, 5.30, 1.10, 1.76),
    'heading': (0.60, 3.10, 0.65, 0.90),
    'double_quote': (0.16, 1.22, 0.62, 0.45),
    'single_quote': (0.12, 1.03, 0.31, 0.46),
    'backtick': (0.39, 1.65, 0.79, 0.59),
    'opening_bracket': (0.12, 1.13, 0.20, 0.37),
    'math': (0.16, 0.72, 0.25, 0.28),
    'partial_character': (0.55, 1.67, 0.72, 0.82),
    'chinese_character': (0.82, 0.69, 0.37, 0.62),
    'letter': (0.00, 0.68, 0.21, 0.15),
}


PUNCTUATION_KINDS = {
    '**': 'bold', '`': 'backtick', '(': 'opening_bracket',
    '[': 'opening_bracket', '$': 'math', '$$': 'math',
    '"': 'double_quote', '“': 'double_quote', '”': 'double_quote',
    "'": 'single_quote', '‘': 'single_quote', '’': 'single_quote',
}



def boundary_kind(s):
    if s == ' ':
        return 'space'
    if s == '\xa0':
        return 'nonbreaking_space'
    if s == '  ':
        return 'double_space'
    if not s.startswith(' '):
        return None
    body = s[1:]
    if body in PUNCTUATION_KINDS:
        return PUNCTUATION_KINDS[body]
    if body and set(body) == {'#'} and len(body) >= 2:
        return 'heading'
    if '\ufffd' in body:
        return 'partial_character'
    if len(body) == 1 and body.isalpha():
        if 'CJK' in unicodedata.name(body, ''):
            return 'chinese_character'
        return 'letter'
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, position = '', '', 0
    else:
        _, previous, before, position = carry
    s = prefix.token_strings[-1]
    early = 1.0 / math.sqrt(position + 1.0)
    value = 0.0
    if s.startswith('\t') and s.isspace():
        width = s.count(' ')
        if width:
            value = (-0.67 if width < 5 else -0.87 if width < 11
                     else -0.80 if width < 19 else -0.66)
            if width % 2 == 0:
                value += 0.10
            if position == 0:
                value = -0.51
        elif '\n' in s:
            value = -0.32 - 0.19 * early
    else:
        kind = boundary_kind(s)
        if kind:
            base, boost, numbered, bullet = BOUNDARIES[kind]
            if previous.endswith('.'):
                value = base + boost * early
                value += numbered * before.strip().isdigit()
                if len(before) == 1 and before.isalpha():
                    value += 0.19 if kind == 'space' else 0.08
                if previous != '.':
                    value *= 0.65
            elif previous in ('-', '*', '•', '·'):
                value = bullet + boost * 0.6 * early
            elif kind == 'space':
                if previous in (')', ']', '>') or previous.endswith('.)'):
                    value = 0.23 + 0.60 * early
                elif previous.endswith(':'):
                    value = 0.09 + 0.32 * early
                elif previous in (' -', ' –', ' —'):
                    value = 0.11 + 0.37 * early
            elif kind in ('bold', 'heading'):
                value = 0.26
                if previous in (' -', ' –', ' —'):
                    value = bullet + boost * 0.4 * early
    return (doc, s, previous, position + 1), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:3714: "label start" detector, with indentation switched off.

In plain terms, the component writes a positive signal when the text is about to start a
new labelled item, and a negative one inside indented code or plain-text indentation.

It responds to the newest token and the one or two before it:

* A bare space token " " after a full stop is positive (about 0.8). This is the space
  after an abbreviation or sentence end ("Fig. 3", "Aug. 9", "No. 4", "end. Then").
  After a line-start list number ("1. 15 days", "2. 12 days", "e. 3.2") it is higher
  (about 1.7).
* After a dash, bullet, or closing bracket, a bare space is weaker (0.25 to 1.0).
* Markdown markers that open a labelled item respond strongly: " **" (bold label) is about
  1.0 by default, 3.0 after a full stop ("7. **DHEA**") and 2.3 after a dash ("- **Title**");
  " ###" is about 1.4 and " ##" about 0.5.
* Indentation in code or text: a tab followed by spaces ("\\t    ") is about -0.75, and a
  tab followed by a newline is about -0.35.
* Everything else is 0.

Units are the component's activation (its contribution size). The program is stateless
across positions: it reads only the current token and what precedes it in the same document.
"""

READS = ()

# Bare space after punctuation that often ends a label or item, and how strongly.
SPACE_AFTER_PUNCTUATION = {
    "-": 1.0, "•": 0.65, ">": 0.35, "?": 0.5, "*": 0.25, ")": 0.25,
    "]": 0.3, "#": 0.3, "//": 0.35, "##": 0.35,
}


def _is_indent(token):
    """A tab followed only by spaces, e.g. '\\t' then four spaces as one token."""
    return len(token) > 1 and token[0] == "\t" and set(token[1:]) <= {" "}


def _is_list_number(text):
    """A line-start list label: a number such as '2', or a single letter such as 'e'."""
    return text.strip().isdigit() or (len(text) == 1 and text.isalpha())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    n = len(prefix)
    prev = prefix.token_strings[-2] if n > 1 else ""
    prev2 = prefix.token_strings[-3] if n > 2 else ""
    prev3 = prefix.token_strings[-4] if n > 3 else ""
    if n > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = prev2 = prev3 = ""  # a new document starts fresh

    # A list number at the start of a line, then a full stop, then this token.
    item_start = prev == "." and _is_list_number(prev2) and prev3 in ("", "\n", "\n\n")

    if item_start and token in (" **", " ###", " ##", " `"):
        value = 3.0 if token == " **" else 1.7
    elif token == " **":
        value = {".": 3.0, "-": 2.3}.get(prev, 1.0)
    elif token == " ###":
        value = 1.4
    elif token == " ##":
        value = 0.5
    elif token == " ":
        if item_start:
            value = 1.7
        elif prev == ".":
            value = 0.8
        else:
            value = SPACE_AFTER_PUNCTUATION.get(prev, 0.0)
    elif _is_indent(token):
        value = -0.75
    elif token == "\t\n":
        value = -0.35
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A spelling-based detector for Python and scientific-programming notation.

The strongest signals are Python filenames, scientific libraries (including
recognizable token fragments of their names), double underscores, and arrows.
Other code words and empty brackets receive smaller values. It is not a
blanket code detector: unrecognized tokens get zero. The small state only
recognizes document starts, import-line starts, and inline-code openings.
"""
READS = ()

ARRAY_PACKAGES = {'numpy', 'scipy', 'sklearn'}
PLOT_PACKAGES = {'matplotlib', 'seaborn', 'plotlib'}
PYTHON_TOOLS = {'conda', 'pytest', 'setuptools', 'jupyter', 'uptools', 'upyter'}
NEURAL_PACKAGES = {'torch', 'tensorflow', 'keras', 'torchvision'}
PYTHON_UTILITIES = {
    'urllib', 'tkinter', 'tempfile', 'timedelta', 'stdlib', 'django',
    'argparse', 'tqdm',
}
ARRAY_TYPES = {'dtype', 'ndarray', 'astype', 'newaxis'}
ARGUMENT_WORDS = {'arg', 'args', 'param', 'parameters'}


def estimate(s, previous, first, line_start):
    t = s.strip()
    w = t.lstrip('./_(-').lower()
    spaced = s.startswith(' ')
    if t in {'.py', 'py', 'Py', '_py', 'pyx', '/py'}:
        return 1.6 if t == '/py' else (0.93 if spaced else 1.25)
    if w in {'ipy', 'pyqt'}:
        return 1.5
    if w in PLOT_PACKAGES:
        return 2.5 if w == 'plotlib' else 2.25
    if w in ARRAY_PACKAGES:
        return 1.65
    if w in NEURAL_PACKAGES:
        return 0.9 if spaced else 1.3
    if w in PYTHON_TOOLS:
        return 1.0 if spaced else 1.4
    if w in PYTHON_UTILITIES:
        return 0.7
    if w in {'pandas', 'andas'}:
        return 0.9 if w == 'pandas' else 0.7
    if w == 'python':
        return 0.6 if spaced else 0.75
    if w in {'np', 'plt', 'tf'} or w in ARRAY_TYPES:
        return 0.6
    if w == 'pyplot' or t in {'.nn', '.optim', '.train', '.tensor', '.savefig'}:
        return 1.1
    if t in {'.array', '.DataFrame', '.Series', '.plot', '.environ', '.fit'}:
        return 0.65
    if t.endswith('__') and not any(c.isalnum() for c in t):
        if t.startswith('/__'):
            return 1.65
        if t.startswith(('.__', ').__')):
            return 1.2
        if t == '__':
            return 0.9 if spaced else 0.77
    if t and set(t) == {'_'} and len(t) >= 8:
        return 0.35
    if t == '__.':
        return 0.57
    if t in {'._', '/_', '`_'}:
        return 0.7
    if '->' in t and not any(c.isalnum() for c in t):
        return 0.14 if '-->' in t else 0.61
    if t == '::':
        return 0.3
    if w == 'src':
        return 0.65 if t.startswith('/') else 0.4
    if w in {'code', 'codes'}:
        return 0.72 if s == ' code' else 0.46
    if t == '代码':
        return 0.7
    if w == 'none' or t in {',None', '=None'}:
        return 0.59 if t[0] in ',=' else 0.49
    if w == 'text':
        return 0.36 if spaced else 0.27
    if w in {'source', 'object', 'function', 'functions'}:
        return 0.2
    if w in ARGUMENT_WORDS:
        return 0.32
    if w == 'kwargs':
        return 0.85
    if t == 'from' and line_start:
        return 0.5
    if t and len(t) >= 8 and len(set(t)) == 1 and t[0] in '=-_%':
        return 0.85 if t[0] == '=' else 0.35
    if '[]' in t:
        return 0.48 if t in {'[]', '[][]'} else 0.28
    if t.startswith('()'):
        return 0.31 if t.endswith(('.', '`', '\\')) else 0.13
    if t == '{}':
        return 0.31
    if t in {'`', '``'}:
        if '\n' in s:
            return -0.15
        if spaced:
            p = previous.strip().lower()
            if '`' in p or not p:
                return 0.14
            return 0.68 if p in {'the', 'running', 'using', 'use', 'with', 'in'} else 0.42
        return 0.08
    if t == '_':
        return 0.14
    if s == '#':
        return 0.96 if first else 0.21
    if s == ' $':
        return 0.17
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, line_start = ('', True) if first else carry[1:]
    value = estimate(s, previous, first, line_start)
    if '\n' in s:
        line_start = not s.rsplit('\n', 1)[-1].strip()
    elif s.strip():
        line_start = False
    return (doc, s, line_start), float(value)

programs.haiku:
"""Code-and-software tokens: a fixed activation per class of token.

The component reads ordinary text as zero but fires on the tokens that name
code and software. Its strongest responses are file extensions (".py"); then
Python-ecosystem names ("Python", "pytest", "conda", "numpy", "pandas", "torch");
then double-underscore identifiers ("__", "._", "/__"), the word "code" and
code-path pieces ("/src", "/pkg"), then the literal "None", the arrows "->" and
"::", spaced inline-code backticks, and "#". Each class predicts its typical
activation (fit on training text); any other token predicts 0. Context (the
code density of the document) was tried and did not help.
"""

READS = ()

PY_EXTENSION = {".py", "py", " py", "Py", " Py", "/python"}
PY_ECOSYSTEM = {"Python", " Python", "python", " python", "pytest", "conda", "numpy",
                " numpy", "pandas", " pandas", "andas", "torch", " torch", "torchvision",
                "plt", "kwargs"}
DUNDER = {"__", " __", "/__", ".__", "._", "__("}
CODE_WORDS = {" code", "Code", " Code", "code", "src", " src", "/src", "pkg", " pkg", "/pkg"}
NONE_LITERAL = {" None", "None", ",None"}
ARROWS = {" ->", "->", "()->", "')->", '")->'}
DOUBLE_COLON = {"::"}
BACKTICKS = {" `", " ``", ":`"}
HASH = {"#"}


def strength(token):
    if token in PY_EXTENSION:
        return 1.1
    if token in PY_ECOSYSTEM or token in DUNDER:
        return 0.8
    if token in CODE_WORDS:
        return 0.6
    if token in NONE_LITERAL or token in ARROWS:
        return 0.5
    if token in BACKTICKS:
        return 0.35
    if token in DOUBLE_COLON or token in HASH:
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    return None, strength(prefix.token_strings[-1])

programs.luna:
"""Approximate this part's bursts around code, code formatting, and source files.

It predicts from the current token: programming vocabulary, code punctuation,
file extensions and common source-tree labels. It does not try to classify whole
passages as code.
"""
READS = ()

CODE_WORDS = {
    "code", "function", "routine", "algorithm", "python", "ruby", "matlab",
    "tactic", "toolbox", "interpreter", "conda", "pytest",
}
SOURCE_LABELS = {"src", "docs", "license", "readme", "serde", "objective"}
FILE_ENDINGS = (".py",)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous_doc, recent = carry if carry is not None else (doc, "")
    if doc != previous_doc:
        recent = ""
    piece = prefix.token_strings[-1].strip()
    lower = piece.lower()
    prior = recent.lower()
    recent = (recent + prefix.token_strings[-1])[-160:]

