    if lower in SOURCE_LABELS:
        value = max(value, 0.30)
    if lower.endswith(FILE_ENDINGS):
        value = max(value, 0.95)
    if lower == "py" and (
        prior.endswith(".") and "/" in prior
        or "pywraplp" in prior or "solver" in prior or "python" in prior
        or "status ==" in prior
    ):
        value = max(value, 0.85)
    if lower.endswith("/python") and ("conda" in prior or "bin" in prior):
        value = max(value, 0.70)
    if "__" in piece:
        value = max(value, 0.68)
    if piece.startswith("_") and lower.endswith("args"):
        value = max(value, 0.50)
    if piece in {"->", "::", "→", "`", "()", "[]", "_", "$"}:
        value = max(value, {
            "->": 0.65, "::": 0.30, "→": 0.20, "`": 0.55,
            "()": 0.22, "[]": 0.40, "_": 0.25, "$": 0.20,
        }[piece])
    if len(piece) >= 8 and set(piece) == {"="}:
        value = max(value, 0.65)
