"""Approximate the dominant repeated-delimiter and line-boundary response.
Double backticks and paired quotes usually produce positive values.
A newline completing a backtick fence is strongly negative; separated
newlines after a short fence header are also negative. Most text is zero.
Fence responses are stronger near the document's beginning. Track the
current line, previous token, header length and document position. Small
negative rules cover math delimiters and comment endings; other text is zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, line, previous, header_age, position = carry or (None, '', '', 100, -1)
    if doc != old_doc:
        line, previous, header_age, position = '', '', 100, -1
    position += 1
    early = 1.0 / (1.0 + position / 20.0)
    token = prefix.token_strings[-1]
    bare = token.strip()
    trailing_ticks = len(line) - len(line.rstrip('`'))
    header_age += 1
    if bare == '```' or (bare == '`' and trailing_ticks >= 2):
        header_age = 0
    value = 0.0

    if '\n' in token:
        if bare == '`':
            if trailing_ticks >= 2:
                value = -2.67 - 1.47 * early
                if token.count('\n') >= 2:
                    value = -3.0 - 2.66 * early
                if previous.startswith(' '):
                    value += 0.6
            else:
                value = -0.45 if token.count('\n') >= 2 else -0.12
        elif bare == '```':
            value = -1.55
        elif bare == '``':
            value = -1.05 if trailing_ticks else -0.25
        elif token.isspace() and '```' in line:
            label = line.rsplit('```', 1)[-1].strip()
            if not label:
                value = -2.5 if '\r' in token else -1.2
            elif header_age <= 4 and len(label.split()) == 1:
                value = -1.9 * 0.55 ** max(0, header_age - 2)
                if label in ('python', 'cpp'):
                    value += 0.45
        elif (line + token).split('\n', 1)[0].endswith('~~'):
            value = -0.8
        elif (line + token).split('\n', 1)[0].endswith('$$'):
            value = -0.6 if token.count('\n') == 1 else -0.4
        elif (line + token).split('\n', 1)[0].endswith('\\]'):
            value = -0.45
        elif token.rstrip().endswith('*/'):
            value = -0.2
    elif bare == '``':
        if token.startswith(' '):
            value = 1.31 + 0.21 * early
        elif trailing_ticks == 1:
            value = -0.12
        else:
            value = 2.35 if previous.isspace() else 1.9 if not line else 2.05
    elif bare == '```':
        value = 0.38 if token.startswith(' ') else 1.04 + 0.15 * early
    elif bare == '`\\' and trailing_ticks >= 2:
        value = -1.27
    elif bare == '$$':
        value = 0.04 if token.startswith(' ') else 0.14

    # Paired single/double quotes, possibly part of an empty string literal.
    match = re.fullmatch(r'[\s=.,(]*([\'"]{2,3})[\s,.;)]*', token)
    if match and len(set(match[1])) == 1:
        quotes = match[1]
        value = (1.1 if quotes[0] == "'" else 0.76) if len(quotes) == 2 else 0.5
        if token.startswith(' '):
            value -= 0.2
        if token.rstrip().endswith((',', '.', ';', ')')):
            value -= 0.4
        if '\n' in token:
            value -= 0.4 if len(quotes) == 2 else 0.5
        if token.count('\n') >= 2:
            value -= 0.2

    line = (line + token).rsplit('\n', 1)[-1][-100:]
    return (doc, line, token, header_age, position), float(value)

