"""Detect a likely new numeral or calendar date, without seeing ahead.
A lone blank is strong after quantity/date introducers, weak after symbols
or numbered labels, and quiet in indentation. English months share this
pattern at a smaller scale. Recent digits damp the blank's response.
"""
READS = ()
MONTHS = frozenset(('january february march april may june july august '
                    'september october november december').split())
MONTH_ABBREVIATIONS = frozenset('jan feb mar apr jun jul aug sep oct nov dec'.split())
APPROXIMATION = frozenset('around about approximately nearly almost roughly circa'.split())
RANGES = frozenset('from between until during among'.split())
PREPOSITIONS = frozenset('of at for with after since before'.split())
FOREIGN_PREPOSITIONS = frozenset('de en von в на из entre nel em في'.split())
RELATIONS = frozenset('to by as than over under into within through across like'.split())
FOREIGN_LINKS = frozenset('à con del el un las le la до от по с и'.split())
DETERMINERS = frozenset('a an his her its their our my your some every'.split())
QUANTIFIERS = frozenset('only least early late last'.split())
MODIFIERS = frozenset(('all both each these those this another additional more most '
                       'not just exactly').split())
AUXILIARIES = frozenset('was were had has have am'.split())
COPULAS = frozenset('is are be being'.split())
CONJUNCTIONS = frozenset('and or but that if while because'.split())
POSSESSIVES = frozenset(("'s", '’s'))
QUANTITY_VERBS = frozenset(('born turned contains containing includes included include '
                           'including uses use using takes take requires weighing '
                           'reaches reached reaching reach exceeds estimated made '
                           'averaged spent').split())
ARITHMETIC_VERBS = frozenset('gives get equals add adding subtract divide calculate'.split())
TIME_MEASURES = frozenset('year years age aged jahre'.split())
LABELS = frozenset(('figure table chapter section step example test case lemma theorem '
                    'equation page line code route highway lesson question version').split())


def number_intro(previous):
    """How strongly the previous token introduces a fresh number."""
    word = previous.strip()
    if not word or '\n' in previous:
        return -0.03
    # Initialisms and capitals used as labels differ from ordinary words.
    if word.isupper() and len(word) > 1:
        return 0.5
    if word == 'A':
        return 1.3
    start = word.lstrip('.(')
    word = (start if start.isalpha() else word).lower()
    if word in APPROXIMATION:
        value = 4.0
    elif word in ('in', 'on'):
        value = 4.05 if word == 'in' or previous.strip().istitle() else 3.65
    elif word in RANGES:
        value = 3.55
    elif word in PREPOSITIONS:
        value = 3.25
    elif word in FOREIGN_PREPOSITIONS:
        value = 3.0
    elif word == 'the':
        value = 3.3
    elif word in DETERMINERS or word in QUANTIFIERS or word in AUXILIARIES:
        value = 3.1
    elif word in RELATIONS or word in COPULAS:
        value = 2.7
    elif word in FOREIGN_LINKS or word in MODIFIERS:
        value = 2.6
    elif word in CONJUNCTIONS:
        value = 2.45
    elif word in POSSESSIVES:
        return 2.8
    elif word in MONTHS:
        return 1.7
    elif word in MONTH_ABBREVIATIONS:
        return 0.35
    elif word in QUANTITY_VERBS or word in TIME_MEASURES:
        value = 2.8
    elif word in ARITHMETIC_VERBS:
        value = 2.35
    elif word in LABELS:
        return -0.1 if previous.strip().istitle() else 0.6
    elif ',' in word:
        return 2.0 if word == '.,' else 1.8 if word == ',' else 1.2
    elif ':' in word or ';' in word:
        return 0.9
    elif word in ('+', '*', '/', '>', '−'):
        return 0.1
    elif word in ('.', '='):
        return 0.47
    elif word.isdigit() or len(word) == 1:
        return 0.38
    elif word.isalpha():
        return 1.25 if previous.startswith(' ') else 0.9
    else:
        return 0.35
    # A lowercase piece with no leading blank may be inside a word.
    return value - (1.0 if not previous.startswith(' ') and previous.islower() else 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, age = ('', 32) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    base = number_intro(previous)
    if token == ' ':
        distance = age + 1
        discount = (0.7 if distance <= 3 else 0.3 if distance <= 8
                    else 0.1 if distance <= 16 else 0.0)
        value = base - discount if base > 1.3 else base
    elif word.lower() in MONTHS and word not in ('may', 'march', 'august'):
        if previous.strip().isdigit():
            value = 0.02
        elif not token.startswith(' '):
            value = 0.4
        else:
            value = 0.28 + 0.32 * base
            if previous.strip().lower() == 'on':
                value += 0.5
    else:
        value = 0.0
    age = 0 if any(c.isdigit() for c in token) else min(age + 1, 32)
    return (doc, token, age), value

