        if token[:1].isspace():
            return 6.5 if previous[-1:].isalnum() else 6.2
        if token.startswith('('):
            return 5.0
        if token.startswith('_'):
            return 5.5
        if token.startswith(('/', '.', '-')):
            return 6.3
        if spelling == 'Ref':
            return 7.5 if previous[-1:].isalnum() else 7.1
        if spelling == 'REF':
