    if word == 'pref':
        return 3.3 if spelling == 'Pref' else 1.8
    if word in {'unref', 'cref'}:
        return 3.7 if word == 'unref' else 2.2
    if word == 'reference':
        return 3.6 if token == 'Reference' else 2.4
    if word == 'references':
        return 1.7
    if word.startswith(('referenced', 'referencing')):
        return 1.2
    if word.startswith('referendum'):
        return 0.7
    if word.startswith('referral'):
        return 3.3
    if word.startswith('refer'):
        return 1.3 if token == 'refer' else 2.3
    if word.startswith('refus'):
        return 3.2
    if word.startswith('prefer'):
        return 0.7 if word.endswith(('ably', 'able')) else 1.3
    if word.startswith(('reform', 'refriger')):
        return 0.3
    if word.startswith(('refund', 'reflex')):
        return 2.1
    if word.startswith('ref'):
        return 1.1
    if token == '参考':
        return 1.7
    if token in {'参', '参照', '引用', '指', '是指', '指的是'}:
        return 0.9  # Reference / referring expressions and their fragments.
    if token.isalpha() and previous.strip().lower() == 'ref':
        return 1.6 if word.startswith('er') else 0.8
