"""Detect tokens that start a short condition or a nested expression.

The largest negative responses are for 'if necessary/needed', negated tests,
and material immediately after doubled opening brackets or template braces.
The response distinguishes subject-led clauses from predicate-only conditions,
and inline braces from braces ending a line. Only two preceding tokens matter.
"""
READS = ()

PERSONAL_SUBJECTS = set('you he she'.split())
OTHER_SUBJECTS = set('I it they that these those'.split())
NECESSITY = {'necessary', 'needed'}
REQUIREMENTS = set('required requested desired wished applicable'.split())
TEST_FUNCTIONS = set('isinstance hasattr len defined callable exists'.split())
POLARITY = set('not true false none'.split())
PREDICATES = set('possible found asked left given used provided supported missing'.split())
QUALIFIERS = set('available helpful unsure different interested known'.split())


def condition(word):
    """Response to the word immediately after 'if'."""
    w = word.lower()
    if w in NECESSITY:
        return -1.43
    if w in REQUIREMENTS:
        return -1.04
    if w == '!' or w == '.':
        return -0.84
    if w.startswith('(!'):
        return -0.28 if w == '(!(' else -0.64
    if w.startswith('__'):
        return -0.78
    if w in TEST_FUNCTIONS:
        return -0.64
    if w in POLARITY or w in {'any', 'more', 'most'}:
        return -0.54
    if w in PREDICATES:
        return -0.48
    if w in QUALIFIERS or w in {'is', 'are', 'has', 'only'}:
        return -0.38
    if word in PERSONAL_SUBJECTS or w == 'let':
        return 0.085
    if word in OTHER_SUBJECTS or w == 'the':
        return 0.03
    if w in {'we', 'there'}:
        return 0.0
    if w in {'a', 'this', 'your'}:
        return -0.07
    if w.startswith('('):
        return -0.045
    if not w:
        return -0.01
    return -0.17


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    word = s.strip()
    if carry is None or carry[0] != doc:
        previous = before = ''
    else:
        _, previous, before = carry
    p = previous.strip()
    pp = before.strip().lower()
    value = 0.001

    if p.lower() in {'if', '(if'}:
        value = condition(word)
    elif p.lower() in {'when', 'unless', 'where'}:
        if word in NECESSITY or word == 'required':
            value = -0.80
        elif word in REQUIREMENTS or word == 'appropriate':
            value = -0.54
        elif word == 'you':
            value = 0.145
        elif word in OTHER_SUBJECTS or word in PERSONAL_SUBJECTS or word == 'we':
            value = 0.09
        elif word in {'a', 'the', 'this', 'your'}:
            value = 0.05
        elif word in PREDICATES or word in {'is', 'are', 'was', 'were'}:
            value = -0.18
        elif word.endswith('ing') and word.isalpha():
            value = -0.12
    elif pp == 'if' and p in PERSONAL_SUBJECTS | OTHER_SUBJECTS | {'we'}:
        if word in {'need', 'want'}:
            value = -0.40
    elif p in {'如', '若', '如果'}:
        if word in {'需要', '需', '要', '涉及'}:
            value = -1.35
        elif word in {'欲', '能', '能够'}:
            value = -0.90
        elif word.startswith(('不', '无', '無', '没', '沒有')):
            value = -0.50
        else:
            value = -0.23

    if '\n' not in previous:
        if '{{' in p and p.endswith('{'):
            value = -1.30 if '\\' in word else -0.80
            if word in {'end', '_'}:
                value = -1.70
        elif p.endswith('[['):
            value = -0.98 if word.isdigit() else -0.55
        elif p.endswith('(('):
            value = -0.40 if previous[:1].isspace() else -0.25
        elif p.endswith('${'):
            value = -0.40
        elif p in {'({', '[{', '([{'}:
            value = -0.35
        elif p == '{':
            if word.isdigit():
                value = -0.15
            elif previous[:1].isspace():
                value = -0.13
            else:
                value = -0.01
        elif p.endswith('{\\') and word == 'partial':
            value = -0.40
        if p.endswith(('{', '((', '[[')) and not word:
            value = -0.025

    return (doc, s, previous), float(value)

