Almost everywhere this component is near zero (typically within +-0.05). It goes
negative on the word right after a conditional opener ("if", "If", "如果", "如", "若")
when that word is the ellipsis of a condition, as in "if necessary", "if needed",
"if required", "if applicable", "if possible", "if desired", "if not", "if any", or
"if (!x)". It is strongest for "necessary" and "needed". Other words after "if" get a
small negative value; subject pronouns after "if" ("if you", "if they") get 0. It also
goes negative on the first token inside an opening "{{", "((", "[{", "[[", "${" or "({".
The values are the typical activations, in the component's own units.
"""

CONDITIONALS = {"if", "If", "IF", "如果", "如", "若"}
ELLIPSIS = {
    "necessary": -1.4, "needed": -1.4, "required": -1.0, "applicable": -1.0,
    "desired": -1.0, "possible": -0.6,
}
NEGATED_OR_TESTED = {"not": -0.5, "any": -0.5, "(!": -0.6, "!": -0.5}
PRONOUNS = {"you", "they", "it", "I", "he", "she", "we", "the", "there", "that", "this"}
OPENERS = {"{{", "((", "[{", "[[", "${", "({"}
OTHER_AFTER_IF = -0.2
INSIDE_OPENER = -0.4

READS = ()


def step(carry, prefix, upstream):
    ids, docs, strings = prefix.token_ids, prefix.document_ids, prefix.token_strings
    if len(ids) < 2 or docs[-2] != docs[-1]:
        return carry, 0.0
    before, word = strings[-2].strip(), strings[-1].strip()
    if before in CONDITIONALS:
        if word in ELLIPSIS:
            return carry, ELLIPSIS[word]
        if word in NEGATED_OR_TESTED:
            return carry, NEGATED_OR_TESTED[word]
        if word in PRONOUNS:
            return carry, 0.0
        return carry, OTHER_AFTER_IF
    if before in OPENERS:
        return carry, INSIDE_OPENER
    return carry, 0.0

"""Word-lexicon program for layers.0.mlp.down_proj:3722 (layer 0 MLP, down projection).

The component writes into the residual stream only on a small set of word families. It
predicts, at each token, a strength set roughly to the average activation those words get
(0 everywhere else):
  - courts and decisions, strongest: "ruling" (1.5 by itself), "decision", "Court",
    "motion", "appeal", "opinion", "majority", "judgment", "finding", and the Chinese
    court words 判决 / 裁定 / 决定 / 法院 / 裁决 (0.7)
  - seeing and sameness: "see", "seen", "saw", "same", "heard", "hearing" (0.55)
  - recency: "today", "previous", "recent", "earlier", "current", "week", "year", "ago" (0.35)
  - research findings: "study", "studies", "found", "held" (0.3)
  - the "<tool_call>" tag (0.65)
Most of the activation is a diffuse small signal on other tokens, which this does not capture,
so the variance explained is modest. The e2e effect is concentrated on the strong words."""
READS = ()

COURT = {"court", "courts", "decision", "decisions", "ruling", "rulings", "ruled", "rejected",
         "dissent", "motion", "appeal", "appeals", "opinion", "majority", "judgment", "judge",
         "finding", "findings"}
SEE = {"see", "seen", "saw", "seeing", "sees", "same", "heard", "hearing", "hear"}
RECENT = {"today", "previous", "previously", "recent", "recently", "latest", "earlier",
          "yesterday", "current", "currently", "prior", "week", "year", "ago"}
STUDY = {"study", "studies", "found", "held", "holding"}
CHINESE_COURT = ("判决", "裁定", "决定", "法院", "裁决")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    if s.startswith("<tool_call>"):
        v = 0.65
    elif w in COURT or any(k in s for k in CHINESE_COURT):
        v = 0.7
    elif w in SEE:
        v = 0.55
    elif w in STUDY:
        v = 0.3
    elif w in RECENT:
        v = 0.35
    else:
        v = 0.0
    return carry, float(v)

