programs.sol:
"""Estimate the component's response to indentation and horizontal spacing.

Its strongest response is to 3, 7, 11, ... spaces: four-column indentation
with the final space attached to the following word's token. Runs just
after a newline respond more strongly than inline spacing. Tabs also activate it,
but a further tab after a whitespace token is largely redundant. Other
spacing widths have much smaller responses; nonbreaking spaces are weaker.
The response fades with token distance from the document start.
Ordinary text is approximated by a near-zero background.
"""
READS = ()


def space_response(n, after_newline):
    if n >= 64:
        return -0.20
    if n == 1:
        return 0.0
    if n % 4 == 3:
        if n == 3:
            return 0.83
        if n == 7:
            return 1.36 if after_newline else 1.20
        if n <= 19:
            return 1.29 if after_newline else 1.04
        return 1.51 if after_newline else 1.20
    if n == 2:
        return -0.06 if after_newline else 0.11
    if n == 4:
        return -0.15 if after_newline else 0.04
    if n % 4 == 1:
        return 0.04 if after_newline else 0.16
    if n % 4 == 2:
        return -0.16 if after_newline else 0.0
    return -0.02 if after_newline else 0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    continuing = carry is not None and carry[0] == doc
    previous = carry[1] if continuing else ''
    age = carry[2] if continuing else 0
    fade = 1.0 / (1.0 + age / 10.0) ** 0.5 - 0.27
    after_newline = previous.endswith('\n')
    value = 0.002
    if text and not text.strip(' \xa0'):
        value = space_response(len(text), after_newline)
        if len(text) % 4 == 3 and age > 0:
            value += (0.38 if len(text) == 3 else 0.55) * fade
        if '\xa0' in text:
            value *= 0.65
        elif len(text) == 3 and previous.endswith('\n\n'):
            value += 0.06
        elif (23 <= len(text) < 64 and len(text) % 4 == 3
              and previous and not previous.strip(' \t')):
            value = 1.51
        elif not previous and len(text) % 4 == 3:
            value += 0.30 if len(text) == 3 else 0.60
    elif text and not text.strip('\t'):
        n = len(text)
        value = (0.67, 0.65, 0.79, 0.74, 0.97, 0.71)[min(n, 6) - 1]
        value += 0.25 * fade
        if n == 1:
            if not previous:
                value = 0.074
            elif not previous.strip(' \t'):
                value = 0.05
            elif previous[-1].isdigit():
                value += 0.05
    elif text.startswith('\t') and not text.strip(' \t'):
        tabs = len(text) - len(text.lstrip('\t'))
        spaces = len(text) - tabs
        if text == '\t' * tabs + ' ' * spaces and spaces % 4 == 3:
            value = {3: 0.78, 7: 0.95, 11: 0.64}.get(spaces, 0.86)
            value += 0.25 * fade
            if tabs > 1:
                value += 0.15
    return (doc, text, age + 1), float(value)

programs.luna:
"""Predict positive pulses on indentation-like whitespace tokens.

The component is usually quiet, but certain all-space run lengths and tabbed
indent shapes have positive activations. A small line-state check helps with
short tab tokens; all non-whitespace text is predicted as quiet.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None:
        has_text, known = False, False
    else:
        old_doc, has_text, known = carry
        if doc != old_doc:
            has_text, known = False, True

    value = 0.0
    if token and all(char in " \t" for char in token):
        width = len(token)
        if "\t" not in token:
            if width >= 3 and width % 4 == 3:
                value = min(1.31, 0.50 + 0.11 * width)
            elif width == 5:
                value = 0.19
            elif width == 16:
                value = 0.98
        elif width == 1:
            value = 0.56
        elif width == 2:
            value = (0.62 if not has_text else 0.34) if known else 0.45
        elif width == 3:
            value = (0.81 if not has_text else 0.09) if known else 0.25
        elif width == 4:
            value = 0.78
        elif width == 5:
            value = 0.70
        elif width == 8:
            value = 0.97
        elif width == 12:
            value = 0.70
        elif width >= 16:
            value = 0.85

    for char in token:
        if char in "\r\n":
            has_text, known = False, True
        elif char not in " \t":
            has_text, known = True, True

    return (doc, has_text, known), value

programs.sol:
"""A lexical approximation to prominent English 'to + word' responses.

Selected starting, trying, doing and helping words are positive; selected
showing, describing and including words are negative. Noun responses cover
such phrases as 'to mind/life/light' and 'to date'. These lexical strengths
are ten times weaker without a preceding 'to', with a few exceptions.
Two-token memory also handles 'to be', 'in mind', 'into account', and offsets
for 'due to', 'according to', and a few infinitive governors.
This captures specific collocations, not infinitives or languages generally;
it omits most weak, token-specific background responses.
"""

READS = ()

# Familiar verbs and phrase nouns, grouped by fitted response strength.
RESPONSES = (
    (1.65, {'help', 'begin', 'attempt'}),
    (1.5, {'start', 'try', 'continue', 'fail'}),
    (0.95, {'do', 'expect'}),
    (0.8, {'want', 'need', 'like', 'strive'}),
    (0.63, {'assist', 'allow', 'aid', 'become', 'learn', 'feel', 'finish',
            'remain', 'appear', 'experience', 'lead', 'cause', 'succeed'}),
    (0.48, {'know', 'believe', 'come', 'change', 'seek', 'claim'}),
    (0.28, {'get', 'have', 'think', 'look', 'avoid'}),
    (-0.75, {'show', 'indicate', 'describe', 'demonstrate', 'explain',
             'reflect', 'showcase', 'include'}),
    (-1.3, {'illustrate'}),
    (-0.5, {'give', 'address', 'incorporate', 'date', 'death'}),
    (-0.38, {'calculate', 'compute', 'determine', 'evaluate', 'define',
             'represent', 'discuss', 'state', 'put', 'store', 'place'}),
    (-0.25, {'make', 'provide', 'add', 'ensure', 'check', 'identify',
             'verify', 'write', 'investigate', 'set', 'form'}),
    (-2.8, {'mind'}),
    (-1.25, {'life', '-date'}),
    (-0.87, {'light'}),
)


def response(word):
    for value, words in RESPONSES:
        if word in words:
            return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, older = carry[1:] if carry and carry[0] == doc else ('', '')
    word = prefix.token_strings[-1].strip().lower()
    to = prev.strip('-_') == 'to'
    value = response(word.lstrip('._')) * (1.0 if to else 0.1)
    if to:
        if older == 'due':
            value += 0.3
        elif older == 'according':
            value += 0.1
        elif older in {'going', 'try', 'trying', 'tried', 'wanted', 'designed'}:
            value -= 0.1
    if to and word == 'be':
        if older == 'considered':
            value = -0.68
        elif older in {'going', 'designed', 'intended', 'wanted'}:
            value = -0.25
        elif older in {'tend', 'tends'}:
            value = 0.6
        elif older in {
            'seem', 'seems', 'seemed', 'have', 'has', 'need', 'needs',
        }:
            value = 0.2
        else:
            value = 0.03
    elif not to:
        if word in {'learn', 'try', 'get', 'life', 'light', 'illustrate'}:
            value = 0.0
        if word in {'started', 'starting', 'beginning'}:
            value = 0.15
        elif word in {'doing', 'done'}:
            value = 0.1
        elif word == 'mind':
            value = -1.12 if prev == 'in' else -0.4
        elif word == 'account' and prev == 'into':
            value = -0.96
        elif word == 'help':
            value = 0.46 if prev in {'can', 'could', 'should', 'may'} else 0.25
        elif word == 'able' and prev == 'be' and older == 'to':
            value = 0.52
    return (doc, word, prev), value

"""A coarse silk/thread and composition-vocabulary detector.

Positive strengths cover silk-radical glyphs, textiles, combining/synthesis,
and economics/statistics words. Characters split across tokens are recognized
by remembering their unfinished UTF-8 bytes, not by interpreting the displayed
replacement symbol. A document-opening '#', '</think>', and 'Joined' have
separate responses. Other silk-radical glyphs get a small default; most other
word-specific responses are left at zero. State resets at document boundaries.
"""
READS = ()

GLYPHS = (
    (3.75, '综'),
    (2.8, '綜绵綿织織绝絕绘繪'),
    (2.0, '统統练練'),
    (1.35, '经經组組绑綁终終纵縱继繼绍紹缠纏绳繩'),
    (0.95, '维維'),
    (0.5, '纯純丝絲纹紋编編绩績繁续續続累纤纖缕縷缝縫纪紀絡'),
)
WORDS = (
    (1.45, {'woven'}),
    (1.00, {'comprehensive', 'textile', 'textiles'}),
    (0.65, set('combination combinations synthetic synth synthesis syn '
               'diverse biodiversity integrated rope ropes polyester weave '
               'weaving cloth cotton wool sewing stitch stitches threading '
               'compreh prehensive binations'.split())),
    (0.30, set('economic statistical statistics economics cohesion cohesive '
               'combined combine combining diversity ribbon canvas sweater '
               'yarn thread threads knit knitting sew linen'.split())),
    (2.90, {'综合', '綜合'}),
    (1.25, {'组合', '組合', '统计', '統計'}),
    (0.65, {'组织', '組織', '组成', '組成', '统一', '統一', '纤维', '纖維',
            '经济', '經濟', '财经', '財經', '维度', '維度', '维修', '維修',
            '维权', '維權', '练习', '練習', '绑定', '綁定'}),
)
WORD_VALUES = {w: v for v, words in WORDS for w in words}
CHAR_VALUES = {c: v for v, chars in GLYPHS for c in chars}
CHAR_VALUES.update({'穿': 0.90, '布': 0.30, '锦': 0.95, '錦': 0.95})

# Tokenizer encodings of UTF-8 prefixes used within the silk-radical block.
UTF8_PIECES = {
    99264: b'\xe7\xb3', 26771: b'\xe7\xb4', 57154: b'\xe7\xb5',
    99324: b'\xe7\xb6', 99977: b'\xe7\xb7', 99777: b'\xe7\xb8',
    99551: b'\xe7\xb9', 22247: b'\xe7\xba', 12491: b'\xe7\xbb',
    44054: b'\xe7\xbb', 163: b'\xe7', 10236: b'\xe7',
}
BANDS = (0.33, 1.68, 2.79, 2.50, 2.62, 1.04, 3.05, 1.59, 1.27)


def byte_piece(token):
    # The tokenizer's single-byte ids for UTF-8 continuation bytes.
    if 222 <= token <= 254:
        return bytes([token - 94])
    if 94 <= token <= 105:
        return bytes([token + 67])
    if token == 255:
        return b'\xad'
    if 106 <= token <= 123:
        return bytes([token + 68])
    return UTF8_PIECES.get(token, b'')


def step(carry, prefix, upstream):
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    pending = b'' if start or carry is None else carry
    piece = byte_piece(int(prefix.token_ids[-1]))
    joined = piece if piece.startswith(b'\xe7') else pending + piece
    pending = joined if piece and len(joined) < 3 and joined[:1] == b'\xe7' else b''
    if piece and len(joined) == 2 and 0xb3 <= joined[1] <= 0xbb:
        return pending, BANDS[joined[1] - 0xb3]
    if piece and len(joined) == 3 and 0xb3 <= joined[1] <= 0xbb:
        char = joined.decode('utf-8', errors='replace')
        if len(char) == 1 and 0x7cf8 <= ord(char) <= 0x7f35:
            # Completed split glyphs are stronger than the ordinary glyph token.
            if char in '絶繰综絵織綿':
                value = 3.3
            elif char in '紹締緒綱継綺綠統统紳':
                value = 2.2
            else:
                value = 1.0
            return pending, value
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = WORD_VALUES.get(word, CHAR_VALUES.get(word, 0.0))
    if token == '#' and start:
        value = 1.25
    elif token == '</think>':
        value = 0.60
    elif token == 'Joined':
        value = 0.67
    elif value == 0.0 and len(word) == 1 and 0x7cf8 <= ord(word) <= 0x7f35:
        value = 0.12
    return pending, float(value)

"""A spelling-based approximation to a predominantly negative 'br' response.

Isolated 'br' fragments, especially HTML line breaks, respond most strongly.
Short syllables and brand/fabric/brake word families respond less strongly.
A few b-r spellings in other scripts and tab-plus-space indentation also respond.
The closing punctuation of a line-break tag keeps a smaller negative response.
Unmatched tokens are left at zero; miscellaneous lexical responses are omitted.
"""
import re

READS = ()

# Whole-token translations and close phonetic spellings of br-related words.
ALIASES = {
    '布': -2.75,             # fabric
    '品牌': -1.9,            # brand
    'ブランド': -3.0,        # brand, Japanese
    'بر': -2.15, 'бр': -3.35, # b-r, Arabic/Persian and Cyrillic
    'ブ': -1.9, 'ブラ': -2.5, # bu and bra, Japanese
}
MEDIUM_STEMS = (
    'break', 'bring', 'bridg', 'branch', 'brac', 'breath', 'bread', 'membran',
)
SUFFIXES = ('', 'e', 's', 'es', 'ed', 'ing')


def response(token):
    raw = token.strip()
    w = raw.lower().strip('_-.;()<>/')
    capitals = raw != raw.lower()
    if w == 'br':
        if raw.startswith('<'):
            return -7.4
        if raw.startswith('-'):
            return -5.0
        if raw.startswith(';'):
            return -6.0
        if raw != raw.strip('_-.()<>/'):
            return -4.0
        if raw == 'BR':
            return -3.05 if token.startswith(' ') else -4.15
        if capitals:
            return -3.4
        return -4.05 if token.startswith(' ') else -5.1
    if w in ALIASES:
        return ALIASES[w]
    if 'бр' in w and len(w) <= 4:  # Short Cyrillic b-r fragments.
        return -1.3
    if re.fullmatch(r'brand(s|ed|ing)?', w):
        return -1.4 if capitals or w.endswith('ing') else -2.1
    if re.fullmatch(r'fabric(s)?', w):
        return -1.6 if capitals or w.endswith('s') else -2.4
    if re.fullmatch(r'brak(e|es|ing|ed)|bricks?', w):
        return -2.3
    if any(w.startswith(stem) and w[len(stem):] in SUFFIXES
           for stem in MEDIUM_STEMS):
        return -1.1
    if 'br' in w:
        if w.startswith(('bright', 'brief', 'brown', 'broadcast', 'breakfast')):
            return -0.05
        if w.endswith('br'):
            return -2.7 if w == 'ibr' else -1.3
        if w.startswith('br'):
            if len(w) <= 4:
                return -1.7 if len(w) == 3 else -1.3
            return -0.6
        return -0.7 if len(w) <= 5 else -0.15
    if token.startswith('\t') and re.fullmatch(r'\t +', token):
        spaces = len(token) - 1
        if spaces in (7, 15):  # Indentation ending at columns 8 and 16.
            return -0.57 if spaces == 7 else -0.50
        return -0.26 if 7 < spaces < 16 else -0.15 if spaces >= 16 else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        count, previous, after_tag = 0, '', False
    else:
        _, count, previous, after_tag = carry
    token = prefix.token_strings[-1]
    value = response(token)
    if token.strip() == 'br':
        if count == 0:
            value = -7.0
        elif previous.endswith('<') or previous.strip() in ('import', 'package'):
            value = -6.1
    if after_tag and token.lstrip().startswith(('>', '/>')):
        value = -1.0 if token in ('>', '><') else -0.35
    is_tag = (token.strip().lower() == '<br'
              or token.strip() == 'br' and previous.endswith('<'))
    return (doc, count + 1, token, is_tag), float(value)

programs.haiku:
"""Layer-0 MLP feature, down_proj component 3728: a word-level detector.

It is strongly negative on the German dative "dem" and its sisters (einem, diesem,
seinem, ihrem, jedem, indem), on "den"-type articles (weaker), on the political and
demographic "Dem-" words (Democratic, democracy, demo, demographic) and on "default".
It is strongly positive on "slot" words (slot, slots, _SLOT), and weakly positive on
place and gap nouns (lot, seat, gap, spot, role, position). Every other token gives 0.
The rule reads only the current token's text, lowercased and stripped of its space.
"""

READS = ()

DEM = {"dem"}
DATIVE = {"einem", "diesem", "seinem", "ihrem", "jedem", "meinem", "unserem", "indem"}
DEN = {"den", "denen", "einen", "einer", "seinen", "diesen", "ihren", "beiden"}
DEMOCRACY = {"democratic", "democrat", "democrats", "democracy", "democr", "demo",
             "demographic", "demographics", "demi", "дем", "民主"}
PLACE = {"lot", "lots", "seat", "seats", "gap", "gaps", "spot", "role", "roles",
         "position", "positions", "window", "slit"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word.startswith("slot") or word == "_slot" or word == "槽":
        value = 3.5
    elif word in DEM:
        value = -4.5
    elif word in DATIVE:
        value = -3.2
    elif word in DEMOCRACY:
        value = -2.0
    elif word in DEN:
        value = -1.2
    elif word.startswith("default"):
        value = -1.0
    elif word in PLACE:
        value = 0.6
    else:
        value = 0.0
    return carry, value

