"""Predict negative German-determiner/default cues and a positive lot cue."""
READS = ()

GERMAN_DETERMINERS = frozenset({
    "der", "die", "das", "den", "dem", "des",
    "ein", "eine", "einen", "einem", "einer", "eines",
