    if word == "lot":
        return None, 0.41
    if word.startswith("default"):
        return None, -0.41
    return None, 0.0

programs.sol:
"""Approximate lowercase suffixes attached to uppercase letters.

Short fragments, technical qualifiers, and separators are the main positive
cues. Familiar word-initial syllables and honorifics are discounted. Number-to-word
and capital-containing name boundaries have a weaker positive response. Z-initial
continuations have a negative correction, especially Zn and Zr.
"""

READS = ()
VOWELS = set('aeiou')
WORD_ONSETS = set('''
bl br ch cl cr dr fl fr gh gl gr kn ph pl pr ps qu rh sc sh sk sl sm sn sp st sw
th tr tw wh wr kr kl
'''.split())
STRONG_JOIN = {'-': 0.42, '.': 0.32, '_': 0.45, '/': 0.34}
NUMBER_JOIN = {'-': 0.14, '.': 0.07, '_': 0.14, '/': 0.1}
NAME_JOIN = {'-': 0.11, '.': 0.07, '_': 0.19, '/': 0.12}
IDENTIFIER_WORDS = set('''
min max mean std var sum avg mod ref ptr sub sup xy test train time type types
val value key name id get set data size count len top bottom base core edit
format port src object assign string matrix weight dev error out input output
info seq reg exp change cap return view model color state index all cols row col
net nets line path
'''.split())


def capital_suffix(cap, body, separator, n, capitals, word_space):
    if separator:
        value = STRONG_JOIN.get(separator, 0.3)
        value += 0.14 if n == 2 else 0.04 if n == 1 else 0.0
        if separator == '-' and n == 1:
            value += 0.33
        if word_space:
            value += 0.1
    else:
        vowel = body[0] in VOWELS or (body[0] == 'y' and n > 1)
        if vowel:
            value = -0.025 - (0.04 if n == 1 else 0.0)
        elif cap.lower() in VOWELS:
            value = 0.1 + (0.17 if n == 1 else 0.09 if n == 2 else 0.0)
        elif cap.lower() + body[0] in WORD_ONSETS:
            value = 0.09 if n <= 2 else 0.0
        else:
            value = 0.24 + (0.16 if n == 1 else 0.09 if n == 2 else 0.0)
        if capitals > 1:
            value += 0.05
        if cap + body in ('Mr', 'Dr', 'Mrs', 'Ms'):
            value -= 0.22
        if cap + body[0] in ('Zh', 'Kh'):
            value -= 0.17
    if n >= 5:
        value -= 0.06
    if body in IDENTIFIER_WORDS:
        value += 0.3
    if not body.islower():
        value -= 0.08
    if cap == 'Z':
        value -= 0.14
    if not separator and cap + body in ('Zn', 'Zr'):
        return -0.16
    return value if cap == 'Z' else max(value, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, capitals = carry[1:] if carry and carry[0] == doc else ('', 0)
    body = token.lstrip('-./_')
    separator = token[:len(token) - len(body)]
    cap = previous[-1:]
    value = 0.0
    if body and 'a' <= body[0] <= 'z':
        n = 0
        for c in body:
            if not ('a' <= c <= 'z'):
                break
            n += 1
        if cap and 'A' <= cap <= 'Z':
            value = capital_suffix(
                cap, body, separator, n, capitals, previous[:1].isspace()
            )
        if value == 0.0 and separator:
            if cap.isdigit():
                value = NUMBER_JOIN.get(separator, 0.0)
                if separator == '-' and len(body) == 1:
                    value = 0.21
            elif any(c.isupper() for c in previous):
                value = NAME_JOIN.get(separator, 0.0)
    for c in token:
        capitals = capitals + 1 if 'A' <= c <= 'Z' else 0
    return (doc, token, capitals), float(value)

programs.luna:
"""Spot Markdown suffixes on common repository-document names and weakly
score hyphen-led technical pieces. Otherwise return zero: the component is
usually inactive.
"""

READS = ()


REPOSITORY_DOC_NAMES = {"README", "CONTRIBUTING"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip()
        if token == ".md" and previous in REPOSITORY_DOC_NAMES:
            return None, 0.65
    if token.startswith("-") and any(char.isalpha() for char in token):
        return None, 0.02
    return None, 0.0

programs.sol:
"""Approximate a number-boundary feature, not numbers themselves.

It is positive on letters/units and arithmetic attached to a number, weaker on
ordinary following words, and negative on dates, clocks, and some count units.
The state is a previous token and 80 characters of text. Split superscripts
are recognized from the decoded prefix; state resets between documents.
"""
import re

READS = ()
NUMERALS = set('''one two three four five six seven eight nine ten eleven twelve
    thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty thirty
    forty fifty sixty seventy eighty ninety hundred thousand million billion'''.split())
UNITS = set('''mm cm km mg kg ml ft lb lbs inch inches foot feet meter meters
    metre metres mile miles yard yards yd degree degrees hz khz mhz ghz pa kpa
    nm mol mmol µm μm µg μg °c °f'''.split())
TIME_UNITS = set('''second seconds sec minute minutes min hour hours day days
    week weeks month months year years ms'''.split())
DATA_UNITS = set('kb mb gb tb kib mib gib byte bytes bit bits'.split())
MONTH = re.compile(r'\b(?:jan\w*|feb\w*|mar(?:ch)?|apr\w*|may|jun\w*|jul\w*|'
                   r'aug\w*|sep\w*|oct\w*|nov\w*|dec\w*)\b', re.I)
LINKS = {
    'and': .51, 'or': .78, 'to': .57, 'is': .53, 'has': .55, 'per': .52,
    'times': .52, 'in': .41, 'on': .53, 'of': -.17, 'by': .24,
    'for': .26, 'from': .33, 'with': .16, 'are': .34, 'was': .26,
    'were': .24, 'divided': .47, 'each': .8, 'can': .44,
}


def after_number(s, tail):
    w = s.strip()
    gap = s[:1].isspace()
    if not w or w[0].isdecimal():
        return 0.0
    low = w.lower()
    run = re.search(r'[0-9]+$', tail)
    n = len(run[0]) if run else 1
    date = bool(MONTH.search(tail))
    if '\t' in s:
        return -.18
    if '�' in s:
        return .3 if gap else .6
    if low in {'am', 'pm', 'a.m.', 'p.m.', 'utc', 'gmt'}:
        return -1.85 if gap and w.isupper() else -1.0
    if MONTH.fullmatch(w) and w[0].isupper():
        return -.28
    if w[0] in '年月日':
        return (-1.0 if '月' in tail else -.4) if w[0] == '日' else -.27
    if low == 'words':
        return -1.45
    if low in DATA_UNITS:
        return -.25
    if low in {'points', 'point', 'views', 'total'}:
        return -.5
    if low in TIME_UNITS:
        return .2
    if low in {'million', 'billion', 'trillion', 'thousand', 'percent'}:
        return 1.1
    if w in {'°', '′', '’'}:
        return 1.35
    if w[0] in '%″^²³⁴⁵⁶⁷⁸⁹⁰×√π' or low == 'pi':
        if w.startswith('%'):
            return .91 if w == '%' else .4
        return 1.12
    if low in UNITS:
        return .85 if gap else 1.03
    if low in {'st', 'nd', 'rd', 'th'} and not gap:
        return .12
    if w.isascii() and w.isalpha() and len(w) == 1:
        if w in {'T', 'Z'} and re.search(r'\d[-:]\d', tail[-24:]):
            return .2
        if gap:
            return .72
        return .95 if re.search(r'[A-Za-z][0-9]+$', tail) else 1.3
    if w in {':', ',', '-'} and not gap:
        if w == ',':
            if date:
                return -.35 if n == 4 else -.53
            return max(-.28, .09 - .07 * n)
        if re.search(r'\d' + re.escape(w) + r'\d+$', tail):
            return -.6
        if w == ':':
            return -.28 if n == 2 else -.05
        return max(-.24, .12 - .09 * n)
    if low == 'at':
        return -.75 if date else (-.45 if n == 4 else .25)
    if gap and low in LINKS:
        return LINKS[low]
    if w[0] in '*+=':
        if w[0] == '*':
            return .5 if '(' in w else .63 if gap else .91
        return (.32 if gap else .63) if w[0] == '+' else .21
    if w in {"'", '"', "'s", '’s', '`', '\\', '$'}:
        if gap:
            return .4
        if w in {'\\', '$'}:
            return .55
        return .65 if w == '"' else 1.05
    if re.fullmatch(r'[._][A-Za-z]', w):
        return .95 if w[0] == '_' else .75
    if w.startswith('..'):
        return .6
    if w[0] in '<>≈~!&→':
        return .45
    if w.startswith('-') and len(w) > 1 and w[1].isalpha():
        return .65
    if w.isalpha():
        if not w.isascii():
            return .3
        return .14 if gap else (.5 if len(w) < 3 else .25)
    return .01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    s = prefix.token_strings[-1]
    numeric = previous[-1:].isdecimal()
    written = previous.strip().lower() in NUMERALS
    value = after_number(s, tail) if numeric or written else -.003
    if written and not numeric:
        value = .09 if s.strip().lower() == 'of' else value * .3
    if not numeric and '�' in previous and re.search(r'\d�+$', tail):
        c = prefix.text_prefixes[-1][-1:]
        if c in '⁰¹²³⁴⁵⁶⁷⁸⁹':
            value = .85
    return (doc, s, (tail + s)[-80:]), float(value)

programs.luna:
"""Estimate a number-boundary signal from the newest token and a little context.

It favors a letter after digits (especially a one-letter Latin symbol), while
ordinary digit runs stay near zero. Familiar number words are a weaker cue.
"""
import unicodedata

READS = ()

NUMBER_WORDS = {
    "zero", "one", "two", "three", "four", "five", "six", "seven",
    "eight", "nine", "ten", "eleven", "twelve", "twenty", "thirty",
    "forty", "fifty", "hundred", "thousand",
}
MONTHS = {
    "jan", "january", "feb", "february", "mar", "march", "apr", "april",
    "may", "jun", "june", "jul", "july", "aug", "august", "sep",
    "sept", "september", "oct", "october", "nov", "november", "dec",
    "december",
}


def step(carry, prefix, upstream):
    i = prefix.position
    document = prefix.document_ids[i]
    if document < 0 or i == 0 or document != prefix.document_ids[i - 1]:
        return None, 0.0

    previous = prefix.token_strings[i - 1].strip()
    current = prefix.token_strings[i].strip()
    digit_context = any(ch.isdigit() for ch in previous)
    word_context = previous.lower() in NUMBER_WORDS

    if not (digit_context or word_context):
        return None, 0.0
    if current.lower() in {"am", "pm"}:
        return None, -1.22
    if any(ch.isalpha() for ch in current):
        cjk = any(
            "CJK UNIFIED IDEOGRAPH" in unicodedata.name(ch, "")
            for ch in current
        )
        if digit_context and cjk:
            return None, 0.05
        if digit_context and len(current) == 1 and current.isascii():
            return None, 1.05
        if digit_context and len(current) == 1:
            return None, 0.85
        return None, 0.47 if digit_context else 0.09
    if current and all(not ch.isalnum() for ch in current):
        if not digit_context:
            return None, 0.01
        if current == ",":
            recent = [
                prefix.token_strings[j].strip().lower().strip(".,")
                for j in range(max(0, i - 6), i - 1)
                if prefix.document_ids[j] == prefix.document_ids[i]
            ]
            if any(token in MONTHS for token in recent):
                return None, -0.50
            return None, -0.02
        if current == ":":
            return None, -0.14
        if current == "/":
            return None, -0.08
        if current == "-":
            return None, -0.10
        if current == ".":
            return None, 0.01
        if current in {"%", "‰"}:
            return None, 0.90
        if current == "+":
            return None, 0.35
        if current == "=":
            return None, 0.22
        if current == ";":
            return None, 0.14
        if current == "(":
            return None, 0.10
        if current == ")":
            return None, -0.04
        if current == "]":
            return None, 0.05
        return None, 0.07
    return None, 0.0

programs.sol:
"""Negative responses to technical vocabulary, skill, and expertise.

Chinese 技术 ('technology/technique') and English 'technical' are strongest.
Technology roots, translations, and skill/method words are weaker. Values
are approximate training averages. A short current-word
buffer recognizes split technical words; 'of' echoes a preceding technical
term. 'Information technology' is attenuated. Other tokens get zero.
"""
from functools import lru_cache

READS = ()
GROUPS = (
    (-6.6, {'技', '技术', '的技术', '和技术', '关键技术'}),
    (-4.9, {'技術', '专业技术', '核心技术'}),
    (-3.1, {'技能', '技艺'}),
    (-2.7, {'科学技术', '经济技术', '高新技术'}),
    (-2.2, {'technique', 'techniques', '技师', '战术'}),
    (-1.8, {'技巧', '技法', '科技', '科技创新', '术', '術'}),
    (-1.5, {'expertise', 'tactical', 'スキル'}),
    (-0.85, {'expert', 'experts', '专家', '專家', '专业', '專業',
             'ech', 'chn', 'ех'}),
    (-0.6, {'tactic', 'tactics', 'strategic', 'mechanism', 'mechanisms',
            'mechanics', 'methodology', 'terminology', '手法', '手段',
            '运维', '机制'}),
    (-0.3, {'strategy', 'strategies', 'knowledge', 'academic', 'practical',
            'mechanical', 'equipment', 'methods', 'innovation', '能力'}),
)
WORDS = {s: v for v, group in GROUPS for s in group}
ENDINGS = {
    'ology': -3.4, 'logy': -3.4, 'ological': -2.8, 'ologies': -2.0,
    'ical': -2.0, 'ically': -2.0, 'ologie': -1.4,
    'ique': -1.8, 'iques': -1.4, 'n': -0.4, 'no': -0.4, 's': -1.0,
}


@lru_cache(maxsize=8192)
def response(raw):
    s = raw.strip().lower()
    if s in WORDS:
        return WORDS[s]
    if '技术' in s or '技術' in s:
        return -3.5 if s.startswith('技术') else -4.9
    if s == 'technical':
        return -4.9 if raw.strip().islower() else -4.4
    if s == 'technically':
        return -3.4
    if s.startswith('technician'):
        return -2.0
    if s in {'technological', 'technologically'}:
        return -2.7
    if s in {'technology', 'technologies'}:
        return -3.2 if raw.strip().islower() else -3.05
    if 'techn' in s:
        return -3.7 if raw.strip().islower() else -3.9
    if s in {'tech', '-tech', 'otech'}:
        return -2.85 if raw.strip().islower() else -2.3
    if s.startswith('tekn'):
        return -2.45
    if s.startswith(('tecn', 'téc', 'тех')):
        return -1.9 if not s.startswith('технолог') else -1.4
    if s.startswith('skill'):
        return -1.65 if s == 'skills' else -1.45
    return 0.0


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, word = '', ''
    if carry is not None and carry[0] == doc:
        previous, word = carry[1:]
    s, value = raw.strip().lower(), response(raw)
    joined = bool(raw) and raw[0].isalpha()
    if joined and 'tech' in word and s in ENDINGS:
        value = ENDINGS[s]
    if s == 'of' and response(previous) < -1.0:
        value = response(previous) * 0.37
    if (s in {'technology', 'technologies'}
            and previous.strip().lower() == 'information'):
        value += 0.8
    if '\ufffd' in raw and prefix.text_prefixes[-1].endswith('技'):
        raw, value = '技', -6.8
    if s == '术' and previous.endswith('技'):
        value = -7.0
    word = ((word if joined else '') + raw.lower())[-32:]
    if not raw or not raw[-1].isalpha():
        word = ''
    return (doc, raw, word), float(value)

programs.luna:
"""A sparse word-level cue for technical and specialist know-how.

The component is most negative on technical terms, and less negative on words
for skill, expertise, methods, and technical fields. The word buffer handles
terms whose spelling is split across tokenizer pieces.
"""
READS = ()

TECH = ("techn", "技术")
SKILL = ("skill", "expert", "habil", "专业", "专家", "实训", "chuyên")
METHOD = (
    "methodolog", "terminolog", "theor", "tactic", "mechan", "ology",
    "academ", "装备", "手段", "sport", "weapon", "artifact",
)


def word_score(word):
    if "技术" in word:
        return -5.8
    if "techniq" in word:
        return -1.9
    if "тех" in word:
        return -1.9
    if any(stem in word for stem in TECH):
        return -3.4
    if any(stem in word for stem in SKILL):
        return -1.2
    if any(stem in word for stem in METHOD):
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    same_doc = (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = carry if same_doc else ""
    if raw and (raw[0].isspace() or not raw[0].isalnum()):
        previous = ""

    current = raw.casefold()
    whole_word = (previous + raw).casefold()
    prediction = word_score(current)
    if prediction == 0.0:
        prediction = 0.5 * word_score(whole_word)

    trailing = ""
    for char in reversed(raw.rstrip()):
        if char.isalnum():
            trailing = char + trailing
        else:
            break
    next_carry = trailing if raw and not raw[-1].isspace() else ""
    return next_carry, prediction

programs.sol:
"""Approximate a lexical response to small counts and indefinite amounts.

Chinese 一 ('one') fused with an object gives the largest response; common
adverbial uses and surrounding grammatical words weaken it. Listed numeral,
indefinite-pronoun and amount classes in several languages get smaller responses.
English 'one' is weakened after negation, identity and reference words. Other
tokens default to zero, including ordinary Arabic digits. The only memory is
the previous token, reset at document boundaries. Amplitudes approximate training
means, rather than counting the objects described by the sentence.
"""
READS = ()

SMALL_NUMBERS = set('two three four five six seven eight nine'.split())
NUMERALS = set('二三四五六七八九十百千万萬亿億两兩几幾')
CLASSIFIERS = set('个個位名只件条條张張本辆輛架座家间間所台层層块塊'
                  '片颗顆粒朵把次回遍种種類类组組批份项項场場部群队隊'
                  '对對双雙句段页頁章首套阵陣瓶支根棵款声聲笔筆处處')
TIME_UNITS = set('年月日天时時分秒周夜刻步')
BODY_PARTS = set('心手脚腳身口眼')
SPAN_OR_ITEM_UNITS = set('段部篇组組间間位份颗顆边邊方')
COUNT_CONTEXTS = set('of in on to into for by about after under from and if where'.split())
ORDINALS = set('first second third last next'.split())
GENERAL_ONE = set('些般样樣旦致定共向贯貫切下是律')
COMMON_ONE_USES = set('直起同闪閃笑流番名页頁代世味种種家年度次')
UNITY = set('同统統唯合单單进進')
ALL_UNITS = CLASSIFIERS | TIME_UNITS | set('人道面股篇大维維')
FOREIGN_NUMBERS = set('zwei drei vier fünf deux trois quatre cuatro cinco '
                      'один два две три'.split())

# Grouped by familiar lexical meanings; responses are approximate amplitudes.
WORD_CLASSES = (
    ('teen numbers', 'eleven twelve thirteen fourteen fifteen sixteen '
     'seventeen eighteen nineteen', 1.08),
    ('tens', 'twenty thirty forty fifty sixty seventy eighty ninety', 0.68),
    ('one occurrence', 'once', 1.35),
    ('repeated occurrence', 'twice thrice', 1.18),
    ('several', 'several', 0.8),
    ('unspecified person', 'someone somebody', 1.28),
    ('unspecified thing', 'something', 0.68),
    ('unspecified place, manner, or person', 'somewhere somehow anyone anybody', 0.49),
    ('universal or absent person/place', 'everyone everybody everywhere nobody', 0.32),
    ('indefinite thing/place, plural one', 'anything anywhere ones', 0.21),
    ('East Asian one / once', 'ひとつ 하나 한번', 4.3),
    ('Japanese amount or degree', '少し いくつか ちょっと なかなか いくら', 2.8),
    ('German inflections of one', 'eine einen einem einer eines', 0.62),
    ('Russian inflections of one', 'одна одно одну одной одним', 1.1),
    ('some / several', 'etwas quelques', 1.05),
    ('German once', 'einmal', 1.75),
)
WORD_RESPONSE = {word: value for _, words, value in WORD_CLASSES
                 for word in words.split()}


def one_phrase(tail):
    if not tail:
        return 2.77
    if tail[0] in '个個':
        return 4.24 if len(tail) == 1 else 5.7
    if tail == '一':
        return 1.8
    if tail in {'百', '二'}:
        return 3.6
    if tail in {'点', '點', '半'}:
        return 6.0
    if tail.startswith('緒'):
        return 1.4
    if tail == 'つ':
        return 5.7
    # Generality ('some', 'same', 'certain') and common lexicalized uses
    # such as 'continually', 'together', 'once', and 'one year'.
    if tail[0] in GENERAL_ONE:
        return 3.2 if len(tail) == 1 else 2.2
    if tail[0] in COMMON_ONE_USES:
        return 5.3 if len(tail) == 1 else 3.3
    if len(tail) > 1:
        return 4.8
    if tail in BODY_PARTS:
        return 8.0
    if tail in TIME_UNITS - {'分'}:
        return 6.2
    if tail in SPAN_OR_ITEM_UNITS:
        return 6.5
    return 7.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.lower()
    value = WORD_RESPONSE.get(word, 0.0)

    if word == 'one':
        value = 0.51 if raw[:1].isspace() else -0.11
        if text[:1].isupper():
            value = 0.68
        if raw[:1].isspace():
            prev_word = previous.lower()
            if not previous:
                value = -0.76
            elif prev_word == 'no':
                value = -0.33
            elif prev_word in {'a', 'every', 'than'}:
                value = -0.10
            elif prev_word in ORDINALS | {'this', 'another', 'is'}:
                value = 0.02
            elif prev_word in {'was', 'were', 'be', 'are', 'become'}:
                value = 0.30
            elif prev_word in COUNT_CONTEXTS or previous in {',', ':', ';'}:
                value = 0.79
    elif word in SMALL_NUMBERS:
        value = 0.78 if raw[:1].isspace() or text[:1].isupper() else 0.53
    elif word == 'ten':
        value = 0.58 if raw[:1].isspace() or text[:1].isupper() else 0.10
    elif word in FOREIGN_NUMBERS:
        value = 0.52 if raw[:1].isspace() else 0.05
