        value = 1.6
    elif text in {'十分', '什么', '什麼', '不少', '许多', '許多', '有些', '所有'}:
        value = 0.9
    elif text == '那':
        value = 0.66
    elif text and all(c in NUMERALS for c in text):
        value = 0.2 if text in '百千万萬亿億' else 0.7 if len(text) == 1 else 1.25
    elif text and text[0] in NUMERALS and len(text) > 1:
        if text[1] in '个個':
            value = 2.0
        elif text[1] in ALL_UNITS:
            value = 1.4 if text[0] in '百千万萬亿億' else 2.8
        else:
            value = 1.2
    elif len(text) > 1 and text[0] in '这這那各每本此某':
        if text[1] in '个個些':
            value = 0.76 if text[0] in '这這各每' else 1.6
        elif text[1] in ALL_UNITS:
            value = 1.9 if text[0] not in '各每' else 1.35
    elif text in ALL_UNITS:
        # A classifier split from its number still receives a count response.
        value = 0.3 if text in CLASSIFIERS else 0.05
        if previous and previous[-1] == '一':
            value = 2.5
        elif previous and previous[-1] in NUMERALS:
            value = 1.1
    return (doc, text), float(value)

