programs.sol:
"""A mostly negative closing-bracket signal, using visible text structure.

Track round, square, and curly bracket pairs, including fullwidth forms and
mixed mathematical intervals. Modulate the response by enclosed token length,
recency of an opener, and a preceding number. Empty pairs and punctuation or
newlines bundled with a closer usually give a much weaker response. Quoted,
multiple, and space-prefixed closers have separate fitted response levels.
Tokens without these closing brackets predict zero; reset between documents.
This approximates the dominant bracket effect, not small word-specific effects.
"""
READS = ()
OPEN = '([{（［｛'
CLOSE = ')]}）］｝'
PAIR = dict(zip(CLOSE, OPEN))


def clamp(x):
    return max(0.0, min(1.0, x))


def response(s, span, opener_has_text, matched, previous):
    strength = clamp((span + opener_has_text - 1.5) / 4.0)
    digit = float(previous.strip().isdigit())
    long_span = clamp((span - 12.) / 25.)
    end = max(i for i, c in enumerate(s) if c in CLOSE)
    tail = s[end + 1:]
    if any(c in OPEN for c in tail):
        return 0.1 - 0.2 * strength
    if '\n' in s:
        return 0.1 - 0.35 * strength - 0.15 * digit + 0.25 * (not previous.strip())
    if any(c.isalpha() for c in tail):
        return 0.0
    if any(c in tail for c in ".。:!?\"'`="):
        return 0.25 - 0.5 * strength - 0.2 * digit
    if any(c in tail for c in ',，;'):
        return 0.1 - 0.85 * strength - 0.3 * digit
    if any(c in tail for c in '\\$^*/+-='):
        return -0.1 - 0.8 * strength - 0.15 * digit
    if tail.strip():
        return 0.1 - 0.5 * strength - 0.15 * digit
    if s.strip() in '}｝':
        return (-0.8 - 0.8 * strength - 0.6 * digit
                + 0.6 * (not previous.strip()) + 0.3 * (not matched) + 0.3 * long_span)
    if s.startswith(' ') and len(s.strip()) == 1:
        return -1.2 - strength - 0.45 * digit + 0.3 * long_span
    if sum(c in CLOSE for c in s) > 1:
        value = -0.8 - 0.7 * strength - 0.5 * digit
        if any(c in s for c in "\"'"):
            value *= 0.75
        return value * (2. / sum(c in CLOSE for c in s)) ** 0.5
    if "'" in s[:end]:
        return -0.9 - 0.8 * strength - 0.1 * digit
    if '"' in s[:end]:
        return -0.6 - 0.55 * strength - 0.15 * digit
    return (-0.2 - 1.9 * strength - 0.5 * digit
            + 0.85 * (not matched) + 0.65 * long_span)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, [], -100, False, '')
    _, t, stack, last_open, opener_has_text, previous = carry
    s = prefix.token_strings[-1]
    spans = []
    local_pairs = 0
    for c in s:
        if c in OPEN:
            stack.append((c, t))
        elif c in CLOSE:
            matches = [i for i, (op, _) in enumerate(stack) if op == PAIR[c]]
            # Mathematical intervals may have different left/right brackets.
            if not matches and c in ')]）］':
                matches = [i for i, (op, _) in enumerate(stack) if op in '([（［']
            if matches:
                i = matches[-1]
                spans.append(t - stack[i][1])
                local_pairs += stack[i][1] == t
                del stack[i:]
    value = 0.0
    if any(c in CLOSE for c in s):
        # Average the matched span and the recency of any opening bracket.
        span = (max(spans) + t - last_open) / 2. if spans else 6.0
        value = response(s, span, opener_has_text, bool(spans), previous)
        if local_pairs == sum(c in CLOSE for c in s):
            start = min(i for i, c in enumerate(s) if c in OPEN)
            end = max(i for i, c in enumerate(s) if c in CLOSE)
            body = s[start + 1:end]
            content = any(c.isalnum() or c in '%*' for c in body)
            value = -1.3 if content else 0.1
        elif spans and max(spans) == 1 and previous.strip() in OPEN:
            value = 0.35
        elif not spans and len(s) == 1:
            value = -1.1 if t < 6 else -0.6
            value -= 0.6 * previous.strip().isdigit()
            if s in '}｝':
                value *= 0.6
    if any(c in OPEN for c in s):
        last_open = t
        opener_has_text = any(c not in OPEN + ' \t\n\r' for c in s)
    return (doc, t + 1, stack, last_open, opener_has_text, s), float(value)

programs.haiku:
"""A closing bracket (")", "]", "}", " )") pushes this component negative. The push is
strongest when the bracket closes a medium-sized group, about 3 to 16 tokens long, and
grows when that group contains digits (dates, formulas, codes). A bracket closing a
one-token group such as "(a)" barely moves it, and so does one right after an indent or
space. A bracket glued to following punctuation or a newline (")," ")." ")\n") is weak.
Everything else is about zero."""

READS = ()
CLOSERS = ")]}"
OPENERS = "([{"
DIGITS = "0123456789"


def _bare(tok):
    """The token is only closing brackets, optionally after one space: ")", " )", "}}"."""
    core = tok[1:] if tok[:1] == " " else tok
    return core != "" and all(ch in CLOSERS for ch in core)


def _size(dist):
    """How strongly a bracket closing a group `dist` tokens after its opener responds."""
    if dist < 0:
        return 0.55  # no opener in this document
    if dist <= 2:
        return 0.35  # "(a)", "(1)"
    if dist <= 4:
        return 0.7
    if dist <= 8:
        return 1.0
    if dist <= 16:
        return 1.1
    return 0.85


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    pos = prefix.position
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if pos > 0 and prefix.document_ids[-2] == doc else ""
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "open": []}  # open: [opener position, saw digit] per open bracket
    stack = carry["open"]
    value = 0.0
    if any(ch in CLOSERS for ch in tok):
        dist = pos - stack[-1][0] if stack else -1
        strength = 2.0 * _size(dist)
        if stack and stack[-1][1]:
            strength *= 1.3  # the group contains digits
        if not _bare(tok):
            strength *= 0.25  # glued to punctuation or a newline
        if prev.strip() == "":
            strength *= 0.25  # right after an indent or a space
        value = -strength
    if any(ch in DIGITS for ch in tok):
        for entry in stack:
            entry[1] = True
    for ch in tok:
        if ch in OPENERS:
            stack.append([pos, False])
        elif ch in CLOSERS and stack:
            stack.pop()
    return carry, value

