    (0.3, 'like unlike difference differences satisfy suitable'),
    # Related lexical families also activate the component.
    (0.8, 'watch watches watched watching worth perfectly'),
    (0.6, 'pass passes passed passing fitness join joined joining'),
)
WORDS = {word: value for value, words in GROUPS for word in words.split()}

# Standard names for equality tests and string comparison in programs.
EQUALITY_TESTS = {
    'strcmp', 'assertequals', 'deepequal', 'partialeq', 'equalto',
}

# Related matching/comparison forms in Chinese, Japanese, Russian, and French.
TRANSLATIONS = (
    (5.0, {'匹配'}),
    (3.5, {'配套'}),
    (2.0, {'配', '配合', '搭配', '照', 'соответств'}),
    (1.8, {'符合', '对应'}),
    (1.55, {'对比', '同比'}),
    (1.55, {'一致', '同步', '合わせ'}),
    (1.15, {'对', '對', '相似', '参照'}),
    (1.0, {'类似', '同样'}),
    (0.9, {'比', '同', '同一', '同じ', '配偶', '适合', '違', '違う'}),
    (0.75, {'不同', '同一个', '相比', '平衡', '相', 'сов', 'rencontre', '比较', '同意'}),
