TRANSLATED = {word: value for value, words in TRANSLATIONS for word in words}


def lexical(token):
    word = token.strip().lower().lstrip('._-(')
    if word in MATCH:
        return 5.3
    if word in MATCH_FORMS:
        return 4.45
    if word in FIT:
        return 2.45 if token.startswith(' ') else 1.15
    if word in {'align', 'aligned'} and not token.startswith(' '):
