# A following article/preposition can continue a relational phrase.
ALIGNMENT = {'align', 'aligned', 'aligns', 'aligning', 'alignment'}
COMPLIANCE = {'comply', 'complies', 'compliance', 'complying'}
APPEARANCE = {
    'look', 'looks', 'looked', 'looking', 'feel', 'feels', 'felt',
    'feeling', 'seem', 'seems', 'seemed', 'sound', 'sounds',
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
