        if previous in APPEARANCE:
            value = 0.65
        elif previous == 'would':
            value = -0.25
    elif word == 'with':
        if previous in ALIGNMENT:
            value = 1.5
        elif previous in COMPLIANCE:
            value = 0.8
        elif previous in {'consistent', 'compatible', 'accordance', 'match'}:
            value = 0.36
    elif word in {'the', 'of'}:
        if previous in MATCH or previous in MATCH_FORMS:
            value = (0.32 if word == 'the' else 0.44) * lexical(previous)
