            value = 0.7
        elif previous in ALIGNMENT and word == 'of':
            value = 0.75

    return (document, word), float(value)

"""Detect alignment gaps: tabs and multi-space tokens after text, not newlines.

Gap strength grows with width, plateaus, and falls for extremely long runs.
Indentation after a newline is nearly silent. Existing whitespace, comment/diff
markers and escaped newlines weaken the response. Repeated nonbreaking spaces,
tabbed words, ellipses and punctuation rulers get smaller responses. All other
tokens predict zero. State resets at document boundaries. Smooth width formulas
capture the main gap signal, leaving token-specific fluctuations unmodeled.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, tail = carry[1:] if carry and carry[0] == doc else ('', '')
    spaces, tabs = token.count(' '), token.count('\t')
    breaks = token.count('\n')
    value = 0.0
    if token.isspace():
        if '\xa0' in token:
            if len(token) > 1:
                value = min(3.0, 0.6 + 0.6 * token.count('\xa0'))
                if previous.endswith('\n'):
                    value *= 0.5
        else:
            if tabs:
                value = min(4.8, 3.9 + 0.35 * (tabs - 1))
                if spaces:
                    value = min(6.8, 3.5 + 0.3 * min(spaces, 7)
                                + 0.14 * max(0, spaces - 7))
                    if spaces > 20:
                        value = 6.1
            elif spaces > 1:
                value = min(5.4, 1.8 + 1.4 * math.log(spaces))
                if spaces > 24:
                    value = max(3.0, value - 0.023 * (spaces - 24))
            if breaks:
                if tabs:
                    value = 1.8
                elif spaces == 2:
                    value = 0.4
                elif spaces == 3:
                    value = 1.2
                else:
                    value = min(3.2, 1.8 + 0.08 * spaces) if spaces > 3 else 0.0
                value /= math.sqrt(breaks)
            if previous.endswith('\n'):
                value = max(0.0, 0.025 * (spaces - 25))
                if tabs and spaces:
                    value = 0.6 + 0.09 * spaces
                elif breaks:
                    value = min(0.8, 0.055 * spaces + 0.1 * tabs)
            elif previous.isspace():
                value = max(0.0, value - (2.9 if previous.endswith('\t')
                                        and tabs else 1.7))
            elif previous.strip() in ('#', '//', '/*', '*'):
                value *= 0.55
            elif (previous.strip() in ('+', '-', '>', 'E') and
                  tail.rsplit('\n', 1)[-1].strip() == previous.strip()):
                value *= 0.5
            elif previous.endswith('\\n'):
                value *= 0.55
            elif tail.endswith('\\n'):
                value *= 0.8
            elif not previous:
                value *= 0.75
    elif token.startswith('\t'):
        value = 1.9
        if previous.endswith('\n'):
            value = 0.0
        elif previous.endswith('\t'):
            value *= 0.12
    else:
        marks = token.strip()
        if marks and set(marks) == {'#'}:
            value = 0.4 if len(marks) == 1 else 0.65
        elif (marks and set(marks) <= {'.', '…'} and
              (len(marks) >= 2 or marks == '…')):
            value = 0.65 if '…' in marks else min(2.8, 0.18 * len(marks) + 0.05)
            if token.startswith(' ') or breaks:
                value *= 0.45
        elif len(marks) >= 4 and len(set(marks)) == 1 and marks[0] in '-=_*':
            value = min(1.9, 0.12 * len(marks)) if len(marks) <= 16 else 0.9
    return (doc, token, (tail + token)[-16:]), float(value)

programs.haiku:
"""Horizontal padding inside a line: tabs and runs of spaces that come after text on
the same line (column alignment, tab-separated fields, numbered-listing gaps).

Layer-0 MLP component 3738 writes into the residual stream only where a whitespace
token sits mid-line. Its activation grows with the width of the gap:
  - a tab (alone, or with spaces) after text: about 4 to 6;
  - a run of 3 spaces: about 1.6; 2 spaces: about 0.3; a single space: 0;
  - indentation at the start of a line (only whitespace back to a newline): 0.
"""

READS = ()

TAB_VALUE = 5.0      # tab, or tab plus spaces, after text on the same line
PURE_TAB = 4.0       # a lone tab after text (e.g. after a line number)
SPACES = {2: 0.3, 3: 1.6}
WIDE_SPACES = 3.8    # four or more spaces after text


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    tok = tokens[-1]
    if not tok or set(tok) - set(" \t"):
        return None, 0.0          # not a run of spaces and tabs
    # Walk back over whitespace-only tokens: stop at text (mid-line) or at a newline
    # or the document's start (line start, i.e. indentation).
    i = len(tokens) - 2
    while i >= 0 and docs[i] == docs[-1] and tokens[i].strip() == "" and "\n" not in tokens[i]:
        i -= 1
    if i < 0 or docs[i] != docs[-1] or "\n" in tokens[i]:
        return None, 0.0
    if "\t" in tok:
        return None, PURE_TAB if tok == "\t" else TAB_VALUE
    return None, SPACES.get(len(tok), WIDE_SPACES if len(tok) > 3 else 0.0)

programs.luna:
"""Estimate the signal carried by indentation and column-alignment whitespace."""
READS = ()

def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if not text or not text.isspace():
        return None, 0.0
    if '\n' in text or '\r' in text:
        return None, 0.9
    width = sum(4 if char == '\t' else 1 for char in text)
    if width < 2:
        return None, 0.0
    size = min(5.7, 1.9 + 0.48 * width)
    return None, 0.65 * size

