              "million": 1.7, "millions": 1.8, "billion": 2.2, "billions": 2.1,
              "trillion": 2.5, "century": 3.5, "centuries": 3.9, "millennium": 2.4,
              "millennia": 2.5, "cent": 2.5, "cents": 1.5, "percent": 1.6,
              "percentage": 1.0, "decade": 1.4, "decades": 1.5, "myriad": 1.1,
              "lakh": 0.9, "crore": 0.8, "countless": 0.9}
CHINESE = {"百": 9.0, "千": 5.5, "万": 1.5, "亿": 1.7, "億": 1.6, "萬": 1.9,
           "百分之": 4.0, "百年": 6.0, "万亿": 2.0, "二": 0.35, "三": 0.25, "四": 0.45}
OTHER = {"천": 1.6, "миллион": 1.5, "два": 0.6, "три": 0.5, "trois": 0.7, "zwei": 0.4}
TIME = {"year": 0.7, "years": 0.6, "month": 0.3, "months": 0.3, "week": 0.2,
        "weeks": 0.4, "hour": 0.35, "hours": 0.3, "generations": 0.5, "mile": 0.4,
        "miles": 0.3, "年": 0.3, "今年": 0.6, "several": 0.4}

LEXICON = {**ONES, **TEENS, **TENS, **MAGNITUDES, **CHINESE, **OTHER, **TIME}
PLURAL_MAGNITUDES = {"hundreds", "thousands", "millions"}
END_OF_DOCUMENT = 0.95


def word_of(text):
    """The token as a bare lower-case word: no leading space, dash or capitals."""
    return text.strip().lstrip("-").lower()


def chinese_magnitude(text):
    """Chinese number characters, also inside compounds: 百 (hundred) and 千 (thousand)
    are strong, 万, 亿 (ten-thousand, hundred-million) weaker."""
    if "百" in text:
        return 5.0
    if "千" in text:
        return 4.0
    if any(ch in text for ch in "万萬亿億"):
        return 1.5
    return 0.0


