"""Local spelling detector for modal auxiliaries and permission words.

Nine English modal spellings produce negative pulses. For lowercase forms
after a space, the pulse is weaker immediately following I/we/you and other
personal pronouns, and stronger after 'which'.
Space and case variants have different strengths; this is not a grammatical
parser. Chinese 可 has a particularly strong pulse, with weaker rules for
可以, 可能, 必须 and compounds containing 可以. 'Available' also fires.
Everything else gets a near-zero baseline. Only the previous token is kept,
and it is forgotten at each document boundary. Small background responses
and rarer spellings are deliberately left unmodeled.
"""

READS = ()

# Lowercase after a space, lowercase without a space, and title case.
MODALS = {
    'can':    (-1.65, -1.06, -1.44),
    'could':  (-1.68, -1.45, -1.31),
    'may':    (-2.03, -1.48, -0.59),
    'might':  (-1.62, -1.35, -1.28),
    'must':   (-1.96, -1.96, -1.87),
    'shall':  (-2.34, -1.62, -1.64),
    'should': (-2.12, -2.07, -2.10),
    'will':   (-1.53, -1.23, -1.01),
    'would':  (-1.75, -1.72, -1.53),
}


def subject_adjustment(word):
    if word in {'i', 'we', 'you'}:
        return 0.86
    if word in {'he', 'she'}:
        return 0.46
    if word == 'they':
        return 0.33
    if word == 'which':
        return -0.30
    if word in {'this', 'that'}:
        return -0.09
    if word in {'there', 'one'}:
        return 0.29
    if word == 'how':
        return 0.46
    if word in {'and', 'or', 'but'}:
        return 0.13
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = -0.002
    if lower in MODALS:
        spaced, bare, title = MODALS[lower]
        if token == ' ' + lower:
            value = spaced + subject_adjustment(previous)
        elif word == lower:
            value = bare
        else:
            value = title
            if lower == 'can' and not token.startswith(' '):
                value = -1.16
    elif lower == 'available':
        value = -0.92 if token == ' available' else -0.79
    elif word == '可':
        value = -3.15
    elif word == '可以':
        value = -1.23
    elif '可以' in word:
        value = -0.73
    elif word == '可能':
        value = -0.38
    elif word == '必须':
        value = -0.80
    elif (token == '\ufffd' and previous
          and prefix.text_prefixes[-1].endswith('可')):
        # The last byte of a separately tokenized Chinese 可.
        value = -3.90
    return (doc, lower), float(value)

