"""Modal verbs (can, should, may, must, would, ...) as a negative activation.

The component is strongly negative on modal auxiliaries and their close
equivalents, the words that set up a following bare verb ("...you can
[find]", "...it should [be]"). Its size depends on the subject just before
the modal: after I / you / we the modal is weaker, after it / that / which /
this it is stronger. Everything else is predicted as 0.
"""

READS = ()

# Obligation / permission modals, and the ones that express possibility or future.
STRONG = {"should", "must", "shall", "may"}
WEAK = {"can", "could", "will", "would", "might"}
# Other ways of saying "can", "must", "available" in other languages.
OTHER = {"available", "disponible", "disponibles", "можно", "peut", "peuvent",
         "doivent", "يمكن", "必须", "可以"}
PERSON = {"i", "you", "we"}
THIRD = {"he", "she", "they"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if raw.strip() == "May":  # the month, mostly, which is only weakly negative
        return None, -0.6
    if raw.strip() == "可":  # Chinese "may / can", very strong
        return None, -3.2
    if word in STRONG:
        value = -2.0
    elif word in WEAK:
        value = -1.6
    elif word in OTHER:
        value = -0.8
    else:
        return None, 0.0
    if prev in PERSON:
        value *= 0.5
    elif prev in THIRD:
        value *= 0.8
    return None, value

