"""Approximate the negative signal for execution and interface instructions.

Action words trigger it; recent computer controls make it stronger. The
signal also continues into 'click on/the', 'go to', and 'once you/the/it'.
Control nouns give weaker responses. Unspaced lowercase click tokens are
treated as code-like names; quoted type fields receive a separate response.
Context resets at each document boundary.
"""
READS = ()

GROUPS = (
    (-.44, 'run runs running ran execute executes'),
    (-.52, 'select selects selecting'),
    (-.24, 'choose choosing clicked clicks'),
    (-.54, 'press pressing pressed enter browse drag dragging paste'),
    (-.64, 'click clicking'),
    (-.38, 'open launch navigate'),
    (-.15, 'type typed typing hover scroll tap toggle'),
    (-.12, 'opens opened opening entered entering'),
    (-.33, 'ctrl'),
    (-.78, '点击 點擊 单击 雙擊 双击 按 按下'),
    (-.55, '选择 選擇 选中 勾选 打开 開啟 进入 進入 新开 运行 执行 を選'),
)
ACTIONS = {word: value for value, words in GROUPS for word in words.split()}
CONTROLS = set('button buttons menu menus window screen tab dialog icon '
               'checkbox cursor mouse keyboard ctrl shift arrow arrows '
               'toolbar browser clipboard windows linux mac terminal desktop '
               'spreadsheet properties 按钮 菜单 窗口 页面 鼠标 键盘'.split())
CONTROL_NOUNS = {
    'menu': -.32, 'menus': -.32, 'arrow': -.22, 'arrows': -.22,
    'window': -.09, 'box': -.09,
}
CONNECTORS = {
    'on': -.25, 'the': -.06, 'to': -.10, 'in': -.12,
    'under': -.5, 'below': -.3, 'above': -.3, 'left': -.3,
    'right': -.25, 'down': -.3, 'next': -.26, 'tab': -.26,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, prev, context = carry
    token = prefix.token_strings[-1]
    word = token.strip().strip('._-/').casefold()
    u = min(context, 3.0)
    value = ACTIONS.get(word, 0.0)
    action = word in ACTIONS
    if word.startswith(('выб', 'наж', 'вой', 'введите')):
        value, action = -.44, True
    if action:
        value -= .35 * u
    if word in {'click', 'clicking'}:
        if not token[:1].isspace() and not token[:1].isupper():
            value = 0.0
        elif prev in {'double', 'right', 'left'}:
            value -= .9
    if word == 'run' and token.strip().isupper():
        value -= .10  # execution-log label
    if word == 'type' and prev.endswith(('"', "'")):
        value -= .57
    if word == 'once':
        value = -.58 if token.strip()[:1].isupper() else -.31
    if word == 'next' and token.strip()[:1].isupper():
        value -= .19
    if word in {'using', 'used', 'simply'}:
        value -= .27 if word == 'simply' else .11
    if word in CONTROL_NOUNS:
        value += CONTROL_NOUNS[word] - .11 * u
    value += CONNECTORS.get(word, 0.0) * u
    if prev in {'click', 'clicking'} and word in {'on', 'the'}:
        value -= 1.25 if word == 'on' else 1.06
    elif word == 'the' and prev in {'open', 'select', 'choose', 'press', 'run'}:
        value -= .20
    if word == 'to' and prev in {'go', 'goes', 'going', 'went'}:
        value -= .75 if prev == 'go' else .35
    if prev == 'once' and word in {'you', 'the', 'it'}:
        value -= .3
    cue = word in CONTROLS or word in {
        'click', 'clicking', 'press', 'pressing',
        '点击', '點擊', '单击', '雙擊', '双击', '按', '按下',
    }
    context = .95 * context + float(cue)
    return (doc, word, context), float(value)

