programs.sol:
"""A detector of opening curly braces, especially quoted-key data literals.

Quoted braces are strongest; quoted square brackets are weaker. Braces used
as code-block boundaries or LaTeX formatting arguments are suppressed.
Only the latest token and the last 100 characters of its document are used;
small activations on ordinary words are left unmodeled.
"""
import re

READS = ()
TEX_FORMATTING = {
    'text', 'textrm', 'textbf', 'textit', 'mathbf', 'mathrm', 'mathsf',
    'mathtt', 'mathit', 'mathcal', 'mathbb', 'operatorname',
    'section', 'subsection', 'subsubsection',
}
TEX_ACCENTS = {
    'hat', 'widehat', 'bar', 'overline', 'underline', 'vec', 'tilde',
    'widetilde', 'dot', 'ddot', 'mathfrak', 'emph',
}


def opening_brace(token, tail):
    left, right = token.lstrip().split('{', 1)
    spaced = token.startswith(' ')
    newline = '\n' in right or '\r' in right
    prev = tail.rstrip()
    if right.startswith('}'):
        return 0.02
    if left.endswith(('_', '^', '$')):
        return -0.18 if '}_' in left else 0.12
    if left.endswith('}'):
        return 0.0
    if right.startswith(('"', "'")):
        if left:
            return 1.29 if left.endswith(':') else 1.04
        return 1.51 if spaced else (1.37 if right[0] == "'" else 1.17)
    if left.endswith(('(', ')', '=')):
        base = {'(': 0.42, ')': 0.55, '=': 0.70}[left[-1]]
        return base if not newline else {'(': 0.24, ')': -0.04, '=': 0.63}[left[-1]]
    if right.startswith('\\"'):
        return 0.73
    if prev.endswith(('_', '^')):
        return 0.0
    if right.startswith('{'):
        return 0.60
    command = re.search(r'\\([A-Za-z]+)$', prev)
    if command and not left:
        name = command[1]
        if name in {'n', 't', 'r', 'd'}:
            return 1.05
        if right.startswith('\\'):
            return 0.02
        if name in TEX_FORMATTING:
            return -0.39
        if name in TEX_ACCENTS:
            return -0.16
        return {'frac': -0.08, 'dfrac': -0.08, 'tfrac': -0.08,
                'begin': 0.03, 'end': 0.0, 'sqrt': 0.10,
                'cite': 0.67, 'ref': 0.35, 'label': 0.16}.get(name, 0.30)
    if right.startswith('\\'):
        return 0.10 if prev.endswith(')') else 0.32
    if left or right.strip():
        return 0.20 if right.isalpha() and len(right) == 1 else 0.75
    scope = prev.endswith((')', '=>')) or re.search(r'\b(else|try)$', prev)
    if newline:
        if scope:
            return (-0.22 if prev.endswith('()') else -0.10) if spaced else 0.08
        if prev.endswith((':', '=', ',', '[')) or re.search(r'\breturn$', prev):
            return 0.65
        return 0.15 if spaced else 0.35
    if scope or prev.endswith('}'):
        return 0.05 if prev.endswith('()') else 0.27
    return 1.10 if prev.endswith(':') else 0.82


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if '{' in token:
        value = opening_brace(token, tail)
    elif re.search(r'\[["\']', token):
        value = 0.35 if token.startswith(' ') else 0.30
    return (doc, (tail + token)[-100:]), float(value)

