"""Line-sensitive whitespace and symbolic separators.

Column gaps and in-line symbols are positive. Ordinary indentation is near
zero, becoming negative for deep indents; extremely long runs have a separate
rising response. Bare stars and repeated equals are negative at line openings
but positive within a line. Space lengths one less
than a multiple of four are common code-indent tokens and have a weaker
in-line response. Literal backslash-n does not count as a line break.

There are also rules for repeated punctuation, nonbreaking spaces and NUL.
The state remembers whether the line is still blank and the preceding token,
resetting at document boundaries. Ordinary words and most punctuation give zero.
"""
READS = ()


def space_run(n, indentation):
    if n <= 1:
        return 0.0
    if indentation:
        if n > 55:  # Separate length response for very long blank-layout runs.
            return min(3.2, -2.7 + 0.08*(n-55))
        return -min(2.7, 0.12 * max(0, n - 14))
    if n % 4 == 3:
        return 0.55 + 0.11 * min(n, 15) - 0.045 * max(0, n - 15)
    return 0.55 + 0.14 * min(n, 18) + 0.018 * max(0, n - 24)


def whitespace(s, opening, previous):
    n, tabs = s.count(' '), s.count('\t')
    continued = previous.isspace() and '\n' not in previous
    if '\n' in s:
        if s.count('\n') > 1:
            return -0.04
        if tabs:
            return 0.08 if opening else 0.25
        return 0.5 * space_run(n, opening)
    if tabs:
        if n:
            return (space_run(4*tabs+n, True) if opening
                    else min(2.8, 0.8 + 0.12*n))
        if continued:
            return 0.35 if opening else 0.5
        if opening:
            return 0.52 if tabs == 1 else max(-3.2, 0.10 - 0.40*(tabs-2))
        return 1.56 if tabs == 1 else min(2.8, 1.15 + 0.29*tabs)
    if '\xa0' in s:
        return max(0.0, 0.11 * len(s) - 0.13)
    if continued:
        return min(3.0, 0.04*n)
    return space_run(n, opening)


def symbols(s, opening, previous):
    b = s.strip()
    if not b:
        return 0.0
    chars = set(b)
    leading, newline = s.startswith(' '), '\n' in s
    n = len(b)
    if chars == {'|'}:
        if leading:
            return 0.9 if b == '|' and not newline else 0.36
        if newline:
            return 1.42
        return (0.0 if n == 1 else -0.68) if opening else 1.0
    if chars == {'='} and n >= 2:
        if leading:
            return min(2.3, 0.7 + 0.27*(n-2))
        if opening:
            return -0.96 if n <= 3 else -0.7
        return 1.07 if n <= 3 else min(2.7, 0.05*n)
    if chars == {'.'} and n >= 3:
        if newline:
            return -0.04
        return -0.45 if opening and n > 8 else min(2.8, 0.4 + 0.038*n)
    if '**' in b and not b.startswith('/'):
        if leading:
            return 0.0 if opening else 0.25
        if newline:
            return 0.8 if s.count('\n') > 1 else 1.13
        if b == '**':
            return -1.69 if opening else 1.9
        return (-1.4 if opening else 1.4) if n < 5 else 0.4
    if '*' in b:
        if b == '*':
            if previous.isspace() and '\n' not in previous:
                return 0.15
            if leading:
                return 0.0 if opening else 0.3
            return -0.85 if opening else 0.76
        if b.startswith(('*/', '/*')):
            return 0.0 if opening else 0.23
        return 0.45 if n <= 4 else 0.0
    # Repeated marks used for rules, blanks, headings and strike-through.
    if len(chars) == 1 and n >= 2:
        c = b[0]
        if c == '-':
            return -0.42 if opening else min(2.8, 0.10*n)
        if c == '_' and n >= 4:
            return -min(2.2, 0.06*n) if opening else min(2.6, 0.04*n)
        if c == '#':
            return 0.0 if opening else min(2.3, 0.5 + 0.1*n)
        if c == '~':
            return -1.7 if opening else (0.1 if n == 2 else 2.0)
    if b in ('!=', '!=='):
        return 0.27
    return 0.86 if s == '\x00' else 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        opening, previous = True, ''
    else:
        opening, previous = carry[1:]
    value = (whitespace(s, opening, previous) if s.isspace()
             else symbols(s, opening, previous))
    if '\n' in s:
        opening = not s.rsplit('\n', 1)[-1].strip()
    elif s.strip():
        opening = False
    return (doc, opening, s), float(value)

