"""Recognize conspicuous table, code-layout, and mathematical separators."""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous_doc, line = carry if carry is not None else (doc, "")
    if doc != previous_doc:
        line = ""

    token = prefix.token_strings[-1]
    left = line
    mark = token.strip()
    value = 0.0

    # Vertical bars and repeated equals/periods make visible table or formula
    # structure; asterisks are useful only as longer divider runs.
    if mark in {"|", "||"}:
        value += 0.95
    elif mark in {"==", "==="}:
        value += 0.85
    elif len(mark) >= 3 and set(mark) == {"="}:
        value += 0.75
    elif mark in {"...", "…"}:
        value += 0.4
    elif mark == "*/":
        value += 0.4
    elif len(mark) >= 3 and len(set(mark)) == 1:
        punctuation = mark[0]
        if punctuation in {"*", "-", "_"}:
            value += 0.55

    math_context = any(ch in left[-80:] for ch in "0123456789=()+-/")
    if mark == "**":
        value += 0.7 if left.strip() else -0.8
    elif mark == "*" and not left.strip():
        value -= 0.55
    elif mark == "*" and math_context:
        value += 0.4
    elif mark.startswith("*(") and math_context:
        value += 0.55
    elif (mark.startswith("*") and len(mark) > 1 and mark[1].isupper()
          and any(ch.isdigit() for ch in left[-60:])):
        value += 0.45

    # Tabs and aligned multi-space gaps are common in source code and listings.
    if token and token.isspace():
        width = len(token.expandtabs(4))
        if "\t" in token:
            value += 1.0 + min(0.7, 0.048 * max(0, width - 4))
        elif width >= 8:
            value += 0.28 + min(0.61, 0.025 * (width - 8))
            if any(ch in left[-100:] for ch in "./{}();:=<>|+-"):
                value += 0.55
            elif left.rstrip().endswith(":"):
                value += 0.4
        elif width >= 3:
            value += 0.2
            if any(ch in left[-80:] for ch in "{}();:=<>|+-"):
                value += 0.3
            elif left.rstrip().endswith(":"):
                value += 0.25
        elif width == 2:
            value += 0.2
            if left.rstrip().endswith(":"):
                value += 0.25

    # Keep only the current line, resetting at document boundaries.
    current = left + token
    if "\n" in current:
        current = current.rsplit("\n", 1)[-1]
    return (doc, current[-160:]), float(value)

