"""A spelling-based approximation, centered on short written 'ol' fragments.
A short token ending in ol gets a large negative value; extra spelling
usually weakens it. Cyrillic ол, Arabic ول and accented spellings behave
similarly but more weakly. Common programming words are exceptions.
Hangul ol syllables also respond.
Single Chinese alcohol, phenol and dissolution characters also respond.
The constants approximate training averages; most other tokens get zero.
"""
import unicodedata
READS = ()
CYRILLIC = str.maketrans('абвгдезиклмнопрстуфхцья',
                        'abvgdeziklmnoprstufhcya')
CODE_ROOTS = ('bool', 'tool', 'control', 'color', 'colour', 'column',
              'console', 'symbol', 'resolv', 'collect')
ALCOHOL_ENDINGS = ('anol', 'enol', 'itol', 'erol', 'cohol')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip('_-./(').lower()
    if word in {'醇', '酚', '溶'}:
        return None, -2.9 if word == '溶' else -3.8
    if word == 'eol':  # End-of-line abbreviation.
        return None, -1.6
    # Hangul vowel o followed by final rieul (l).
    if len(word) == 1 and unicodedata.normalize('NFD', word).endswith('ᅩᆯ'):
        return None, -2.2 if word == '올' else -1.5
    if not word.isalpha():
        return None, 0.0
    script = 1.0
    if 'ол' in word:
        word, script = word.translate(CYRILLIC), 0.75
    elif 'ول' in word:
        word, script = word.replace('ول', 'ol'), 0.5
    elif any(c in word for c in 'óöôł'):
        word = ''.join(c for c in unicodedata.normalize('NFD', word)
                       if not unicodedata.combining(c)).replace('ł', 'l')
        script = 0.27
    at = word.rfind('ol')
    if at < 0:
        return None, 0.0
    left, right = word[:at], word[at + 2:]
    if right in ('', 's'):
        strength = (4.9, 3.9, 3.1)[at] if at < 3 else 1.2
        if at == 1 and left in 'aeiu':
            strength = 4.9
        elif left.endswith('c'):
            strength *= 0.65
        elif left.endswith('p'):
            strength *= 0.8
        elif left.endswith('o'):
            strength = 2.4 if at == 1 else 1.6
        if token[0].isspace():
            strength *= 0.85
        if right:
            strength *= 0.75
        if word.endswith(ALCOHOL_ENDINGS):
            strength = 4.5 if len(word) <= 4 else 2.0
        if script == 0.75 and at >= 2:
            strength *= 0.35
    else:
        strength = 1.4 / (1 + 0.15 * len(right))
        strength *= 0.5 if at == 1 else 0.6 ** max(0, at - 1)
        if right.startswith('d'):
            strength *= 0.1
        if word.endswith('ology') and at <= 2:
            strength = 1.4
        if script == 0.75:
            strength *= 1.6 if at == 0 and right in {'a', 'y', 'ь'} else 0.6
    if script == 0.5:
        strength /= 1 + at
    if any(root in word for root in CODE_ROOTS):
        strength *= 0.07
    elif word.startswith(('school', 'whole', 'hold', 'follow')):
        strength *= 0.12
    return None, float(-strength * script)

