# whitespace, math sign/open bracket, closing bracket, number,
# single-letter variable, short word, longer word, other punctuation.
BASE = {
    ' -':  (0.19, 0.31, 0.65, 0.92, 0.63, 1.25, 1.61, 0.83),
    ' –':  (0.22, 0.30, 0.43, 0.56, 0.31, 0.42, 0.60, 0.35),
    ' —':  (0.12, 0.17, 0.36, 0.48, 0.34, 0.35, 0.53, 0.27),
    ' --': (-0.04, 0.10, 0.29, 0.27, 0.22, 0.37, 0.46, 0.12),
    ' /':  (0.18, 0.21, 0.17, 0.35, 0.22, 0.56, 0.58, 0.34),
    ' |':  (0.05, 0.07, 0.44, 0.28, 0.01, 0.36, 0.54, 0.21),
}
EARLY = {' -': 3.57, ' –': 1.90, ' —': 1.15,
         ' --': 0.09, ' /': 0.39, ' |': 1.29}
START = {' -': 1.91, ' –': 0.99, ' —': 0.24,
         ' --': 0.0, ' /': 0.25, ' |': 0.16}


def preceding_class(text):
    c = text[-1:]
    if not c or c.isspace():
        return 0
    if c in '=+*/<>≈⇒,:;([{':
        return 1
    if c in ')]}':
        return 2
    if c.isdigit():
        return 3
    word = re.search(r'([^\W\d_]+)$', text)
    if word:
        word = word[0]
        if word.isascii() and len(word) <= 3:
            return 4 if len(word) == 1 else 5
        return 6
    return 7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, text = 0, ''
