            value += EARLY[token] / math.sqrt(position + 1)
        if position == 0:
            value = START[token]
    elif token == ' import':
        line = text.replace('\\n', '\n').rsplit('\n', 1)[-1]
        if re.search(r'\bfrom\s+[\w.]+$', line):
            value = 1.06 * (1 + 2.4 / math.sqrt(position + 1))
        else:
            value = 0.14
    return (doc, position + 1, (text + token)[-160:]), float(value)

