"""Spaced dash, bar and slash separators, and Python 'import' after a name.

The component reads the token that sets off a second item after a word, number or
closing bracket, as in "Title - Site", "Houston - ECE", "(2a -6)", "| category",
"grep -n", "from x import". It is strongest for the spaced dash " -", weaker for the
dashes " –" and " —", the bar " |", the slash " /" and " --". Within a document it is
strongest near the start and fades over the first few hundred tokens. It is nearly
silent after a space or an operator sign (as in "= -1" or "+ -").
"""

READS = ()

# Typical strength of each separator, with a full word or bracket before it.
SEPARATORS = {" -": 1.9, " –": 1.0, " —": 0.7, " --": 0.5, " |": 0.7, " /": 0.6, " import": 1.2}


def _level(text):
    """How strongly the token before a separator invites it."""
    if not text:
        return 0.25
    if text[-1].isdigit():
        return 0.8
    if len(text) == 1 and text.isalpha():
        return 0.7  # a lone letter, as a maths variable
    if text[-1].isalpha() or text[-1] in ")]}\"'`":
        return 1.0
    return 0.25  # a space, operator sign or other punctuation before it


def _early(pos):
    """Separators near the start of a document are stronger."""
    return 0.75 + 0.8 / (1 + pos / 15)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    pos = 0 if carry is None or carry[0] != doc else carry[1] + 1
    carry = (doc, pos)
    tok = prefix.token_strings[-1]
    if tok not in SEPARATORS:
        return carry, 0.0
    prev = prefix.token_strings[-2] if pos > 0 else ""
    return carry, SEPARATORS[tok] * _level(prev) * _early(pos)

