        if size == 2:
            base = 4.4 if word.isupper() else (4.0 if boundary else 3.6)
            value = -base * (1.0 - 0.6 * romance)
            if not (word.islower() or word.isupper()):
                value = -2.0
            if raw.startswith(('.', '/')):
                value = -5.2
            elif raw.startswith('('):
