            base = 4.0 if lower in {'ios', 'los'} else 3.1
            value = -base * (1.0 - 0.5 * romance)
            if lower[0] in 'huñ':
                value = -1.9
        elif size == 4:
            # Past participles, first-person plural verbs, adjective endings.
            if lower in {'ados', 'idos'}:
                value = -0.6
            elif lower in {'amos', 'emos', 'imos', 'icos', 'ivos'}:
                value = -1.1
