        value = -1.9
    elif lower == 'ос':
        value = -1.8 if boundary else -2.8
    elif lower.endswith('ос') and len(word) == 3:
        value = -0.8
    elif word == 'وس':
        value = -1.8
    elif lower in {'linux', 'android', 'unix'} or word in {'Windows', 'Mac'}:
        # Operating-system names related to the OS abbreviation.
        value = -0.8 if lower == 'linux' else -0.4
    elif lower == 'tan':
        value = -0.4
    elif lower == 'sin':           # sine, including nonmathematical uses
        value = -0.8
    elif lower.startswith('cosin'):
        value = -1.0
