"""Local C/soft-c spelling response, strongest on short ce/ci/cy fragments.

Length attenuates the response, except in cell, cent-, citation, and
citizenship families. Isolated C and Cyrillic tse (ц) also respond.
Internal soft c is weaker than initial soft c. A few corresponding
non-Latin spellings and cell/city/center translations are recognized too.
Context is not modeled.
"""
READS = ()

# Following letter -> values for lengths 2, 3, 4, 5, and 6+.
SOFT_C = {
    'e': (-1.2, -1.6, -1.0, -0.7, -0.3),
    'i': (-3.5, -2.3, -1.1, -1.0, -0.4),
    'y': (-2.7, -1.1, -1.1, -1.0, -0.8),
}
INTERNAL = {
    'e': (-0.5, -0.5, -0.2, -0.1),
    'i': (-1.4, -1.0, -0.4, -0.3),
    'y': (-1.7, -0.2, -0.1, 0.0),
}

# Phonetic counterparts and translations of cell, city, and center.
CROSS_SCRIPT = {
    'シ': -1.3, 'セ': -0.9, 'サイ': -2.7,
    '시': -0.65, '사이': -1.4, 'ص': -1.0,
    '胞': -1.9, '中心': -0.9, '城市': -0.6,
    'センター': -2.0, 'セル': -1.2,
}
VOWEL_ACCENTS = str.maketrans('éèêëíìîïýÿ', 'eeeeiiiiyy')


def spelling_value(s):
    word = s.lstrip(' \t\n\r_./(-[\'":,°')
    w = word.lower().translate(VOWEL_ACCENTS)
    n, capital = len(w), word[:1].isupper()
    boundary = bool(s and s[0].isspace())
    if w == 'c':
        return (-0.55 if capital else -0.28) - (0.16 if boundary else 0)
    if w == 'cm':
        return -0.75
    if w.startswith(('cancer', 'council')):
        return -1.0
    if w.startswith('ц'):
        if n == 1:
            return -3.0 if boundary or capital else -2.0
        if n == 2:
            return -2.2 if w[1] == 'и' else -1.0
        return -1.3 if n == 3 else -0.65
    if 'ц' in w:
        j = w.index('ц')
        return (-1.1 if n - j == 2 else -0.3) if j == 1 else 0.15
    if w.startswith(('ce', 'ci', 'cy')):
        value = SOFT_C[w[1]][min(n, 6) - 2]
        if n == 2:
            if w[1] == 'e':
                value = -1.65 if word.isupper() else -2.7 if capital else (
                    -2.3 if boundary else -1.2)
            elif word.isupper():
                value += 0.6
        elif n == 3:
            value += 0.6 if w[2] in 'aeious' else 0.0
            value -= 0.5 if boundary and w[1] == 'e' else 0.0
        if w.startswith('cell'):
            return -2.1 if n == 4 else -1.85
        if w.startswith('cent'):
            if w.startswith(('centur', 'centuries')):
                return -0.2
            return -1.9 if n <= 5 else -1.0
        if w.startswith('citat'):
            return -2.5 if not w.endswith('s') else -2.0
        if w.startswith('citiz'):
            return -2.1 if w.startswith('citizenship') else -1.5
        if w.startswith(('cyber', 'cyt', 'cyst')):
            return -1.5
        if w.startswith('cement'):
            return -1.3
        if w.startswith('ciudad'):
            return -1.9
        return value
    if w.startswith(('acell', 'ocyte')):
        return -1.7
    if w in ('recent', 'science'):
        return -0.55
    if w == 'sciences':
        return -1.35
    if w.startswith(('accent', 'acet')):
        return -1.2
    if w.startswith('acid'):
        return -0.6
    if w == 'ice':
        return -0.05
    value = 0.0
    for j in range(min(3, n - 1)):
        if w[j] == 'c' and w[j + 1] in 'eiy':
            if j == 1:
                value += INTERNAL[w[j + 1]][min(n - j, 5) - 2]
            elif j == 2 and n - j == 2:
                value -= 0.5 if w[j + 1] in 'iy' else 0.08
    return CROSS_SCRIPT.get(word, value)


def step(carry, prefix, upstream):
    return None, float(spelling_value(prefix.token_strings[-1]))

programs.haiku:
"""Soft-C detector for layers.0.mlp.down_proj:3759.

The component writes a strong negative signal into the residual stream on tokens whose
spelling starts with a "soft" C: the letter c followed by e, i or y, which is pronounced
/s/ in English (ci-, cy-, ce-: "city", "cell", "cent", "cycle", "center", "citizen").
Its size depends on which soft-C family the token starts with:

- "ci" and "cy" starts (ci, cy, cit, cin, cyt...) are the strongest;
- "ce" starts (ce, cell, cent, cer, city, center...) are a bit weaker;
- a Cyrillic "ц" (the "ts" sound) behaves like a soft C;
- a lone capital "C" is moderately negative, a lone lowercase "c" weakly so;
- hard-C starts ("ca", "co", "cl", "ch", "cr"...) and every other token give about 0.

The prediction is the activation itself (negative values), so no sign flip is needed.
Stateless: each token is judged on its own text.
"""

READS = ()

# Activation predicted for each family of token starts (values are typical means).
SOFT_CI = -1.6     # c + i or y: ci-, cy-, cit-, cin-, cyt-
SOFT_CE = -1.2     # c + e: ce-, cell-, cent-, cer-, city-
LETTER_C_UPPER = -0.7   # "C" on its own, e.g. "Michael C. Smith"
LETTER_C_LOWER = -0.35  # "c" on its own
CYRILLIC_TS = -1.4      # "ц" (ts sound)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if token.strip() == "C":
        value = LETTER_C_UPPER
    elif word == "c":
        value = LETTER_C_LOWER
    elif word[:1] == "c" and word[1:2] in ("i", "y"):
        value = SOFT_CI
    elif word[:1] == "c" and word[1:2] == "e":
        value = SOFT_CE
    elif word[:1] == "ц":
        value = CYRILLIC_TS
    return carry, float(value)

programs.luna:
"""Predict modest negative responses to soft-C and cell-related spellings.

The token clues are imperfect proxies for the component's context-sensitive signal.
"""

import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    spelling = "".join(
        char for char in unicodedata.normalize("NFKD", token)
        if not unicodedata.combining(char)
    )

    if any(part in spelling for part in ("cell", "cyt", "ocyte", "胞")):
        guess = -1.5
    elif "ц" in spelling:
        guess = -1.3
    elif spelling.strip() == "c":
        guess = -0.65
    elif any(pair in spelling for pair in ("ce", "ci", "cy")):
        guess = -0.65
    elif spelling.lstrip().startswith("c"):
        guess = -0.14
    else:
        guess = 0.0

    return None, 0.44 * guess

programs.sol:
"""Conditional words, plus compounds about language and communication.

The main response is to 'if' and 'when', including programming syntax and
several translations. Indented branches are stronger; 'as/even/only if'
are weaker. A second response estimates language-related compounds such as
'language model', 'text file', and 'speech recognition'. Other tokens get
zero. These are approximate lexical rules, not a complete semantic parser.
"""
import re

READS = ()
CONDITIONS = {
    'elif': 1.2, 'elseif': 1.2, 'whenever': 0.55, 'unless': 0.22,
    'iff': 0.29, 'wenn': 0.59, 'если': 0.38,
    'ifdef': 1.35, 'ifndef': 1.35,
}
FUNCTION_WORDS = set('''
    a an the of to from and or but for in on at by with as is are was were
    be been being this that these those it its their our your my his her
    which who what where when how why if not no can could should would
    may might will do does did have has had i you he she we they them us
    me than then so such all any some other also into out up down about
    over under after before between without only even there here
'''.split())
MEDIA_TERMS = set('''
    text language speech voice audio sound chat syntax communication
    word sentence message font
'''.split())
COMPOUNDS = {
    'text': {'file': 1.4, 'files': 1.25, 'size': 1.0, 'editor': 0.8,
             'plain': 1.05, 'html': 1.05, 'align': 1.3},
    'language': {'model': 1.4, 'models': 1.2, 'learning': 1.4,
                 'processing': 0.6, 'barriers': 2.7},
    'speech': {'quality': 2.2, 'production': 2.1},
    'voice': {'actor': 1.1, 'acting': 1.5, 'over': 1.7},
    'audio': {'interface': 1.1, 'recorder': 0.63, 'stream': 0.9},
    'chat': {'interface': 1.0, 'bot': 1.0, 'bots': 1.0},
    'communication': {'skills': 1.4},
    'syntax': {'error': 1.2, 'errors': 0.95,
               'highlight': 0.9, 'highlighting': 1.0},
}


def previous_word(text):
    match = re.search(r'([A-Za-z]+)\W*$', text)
    if not match:
        return ''
    # At a camel-case boundary, getText exposes the qualifier 'text'.
    words = re.sub(r'([a-z])([A-Z])', r'\1 \2', match[1]).split()
    return words[-1].lower()


def conditional(token, word, before, first):
    lower = word.lower()
    if lower == 'when':
        if first and word == 'When':
            return 1.42
        return 0.84 if word == 'when' else 0.95
    if lower in CONDITIONS:
        if lower in ('wenn', 'если') and word[0].isupper():
            return 0.72 if lower == 'wenn' else 0.50
        return CONDITIONS[lower]
    if word.startswith('如果'):
        return 0.95 if word.startswith(('如果你', '如果您')) else 0.67
    if word in ('若', '若是'):
        return 0.60
    if lower != 'if':
        return 0.0

    line = before.rsplit('\n', 1)[-1]
    match = re.search(r'(\w+)\W*$', before)
    previous = match[1].lower() if match else ''
    numbered = bool(line.strip()) and line.strip().isdigit()
    comment = line.rstrip().endswith(('#', '//', '*'))
    indented = bool(line) and not line.strip()
    if token.startswith('-'):
        return 2.0  # conditional directives, e.g. v-if
    if token.startswith('.'):
        return 1.74
    if word == 'if':
        if '\t' in token:
            return 1.75
        if previous == 'else':
            return 1.54
        if numbered:
            return 1.35
        if indented or comment:
            return 1.48
        if previous in ('even', 'only', 'as'):
            return 0.55
        if token == 'if':
            return 1.35 if not line.strip() else 1.08
        return 1.30 if token.startswith('(') else 0.93
    if first:
        return 1.48
    if word == 'IF':
        return 1.32 if not token.startswith(' ') else 1.2
    return 1.37 if comment else (1.24 if token == 'If' else 1.16)


def language_compound(tail, token, word):
    previous = previous_word(tail)
    head = word.lstrip('/_-').lower()
    value = 0.0
    if previous in MEDIA_TERMS:
        if head.isascii() and head.isalpha() and head not in FUNCTION_WORDS:
            value = 0.4 if previous in ('language', 'speech', 'syntax') else 0.25
        value = COMPOUNDS.get(previous, {}).get(head, value)
        if previous == 'speech' and head and 'recognition'.startswith(head):
            value = 1.4 if token.startswith('.') else 3.2
    if re.search(r'speech([_.])rec[a-z]*$', tail.lower()):
        if (tail + token).lower().endswith('recognition'):
            value = 1.4 if '.rec' in tail.lower() else 3.0
    if tail.endswith(('语', '語')):
        value = {'料': 2.2, '态': 1.35, '態': 1.35}.get(word, value)
    if tail.endswith(('语言', '語言')) and word in ('处理', '處理'):
        value = 0.9
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    token = prefix.token_strings[-1].replace('\\n', '\n').replace('\\t', '\t')
    word = token.strip().lstrip('_-.\"“(#;—')
    before = tail + token[:len(token) - len(token.lstrip())]
    value = conditional(token, word, before, first)
    if value == 0.0:
        value = language_compound(tail, token, word)
    return (doc, (tail + token)[-256:]), value

