        if word[:1].isupper():
            return None, 1.22
        if token == word:
            return None, 1.3
        return None, 1.06
    if folded == "when":
        return None, 0.85
    if folded == "whenever":
        return None, 0.6
    if folded == "unless":
        return None, 0.15
    if folded == "iff":
        return None, 0.3
    if word.startswith("如果"):
        return None, 0.66
    return None, 0.0

