    (0.8, 'grant granted granting'),
    (0.65, 'grants'),
    (0.43, 'award awarded licensed ordained vested receipt'),
    (0.23, 'awards license permission'),
    (0.18, 'expert'),
    (0.25, 'experts'),
    (0.64, 'tutoring'),
    (0.38, 'authorized'),
    (0.6, 'professor proficient impart bestowed'),
    (0.3, 'professors prof proficiency expertise mentor tutor '
          'tutors instructor gifted'),
    (0.53, 'authorize authorization unauthorized'),
    (0.34, 'permissions conferred endowed'),
    (0.4, 'confer'),
    (0.28, 'licensing'),
    (0.17, 'licenses'),
    (0.49, 'sublicense'),
