    "Western", "Eastern", "Northern", "Southern", "District", "district", "State",
    "state", "Province", "Royal", "Haiti", "Arizona", "Nashville", "Milwaukee",
    "Francisco", "Europe", "Africa", "Asia", "India", "China", "Russia", "Japan",
    "America", "Canada", "Britain", "France", "Germany",
}
