import re

READS = ()
LABELS = {
    'fig': 3.30, 'figure': 3.65, 'table': 2.80, 'page': 1.75,
    'line': 0.75, 'section': 0.55, 'chapter': 0.70, 'example': 1.30,
    'paragraph': 2.0, 'footnote': 1.70, 'p': 0.20, 'pp': 0.50,
    'eq': 0.95, 'equation': 0.50,
