YEAR = re.compile(
    r'\b(?:' + MONTH_NAMES + r')\.?\s+\d{1,2}(?:st|nd|rd|th)?\s*,\s*$', re.I
)
YEAR_NO_COMMA = re.compile(
    r'\b(?:' + MONTH_NAMES + r')\.?\s+\d{1,2}\s+$', re.I
)
