        anchor = text[:-run] if run else text
        digit = int(token)
        value = 0.01 - (0.05 if digit == 0 else 0.04 if digit >= 8 else 0.0)
        if not run:
            if text.endswith('_'):
                value += 0.43 + 0.55 * bool(re.search(r'\b[A-Z][A-Z_]*_$', text))
                value -= 0.13 * text.endswith('__')
            value += 0.23 * bool(re.search(r'\d, ?$', text))
            value += 0.40 * text.endswith('{')
            value += 0.25 * text.rstrip().endswith(('<', '>'))
        label = LABEL.search(anchor)
        if not label and anchor.endswith('['):
            label = LABEL.search(anchor[:-1])
        if label:
            word = label[1].lower()
            reference = word in ('fig', 'figure', 'table')
            strength = LABELS[word]
            if label[1].islower():
                strength -= 1.50 if reference else 0.15
            if label[2]:
                strength -= 1.0
            if reference and anchor.endswith('['):
                strength -= 1.05
            value += strength * (0.70 if reference else 0.60) ** run
        if YEAR.search(anchor):
            value += 0.60 if not run else 0.18 * 0.65 ** (run - 1)
        elif YEAR_NO_COMMA.search(anchor):
            value += 0.52 * 0.40 ** run
