"""Approximate an early-document separator response.

Line breaks and punctuation receive the strongest negative pulse, with
weaker pulses for common function words. The pulse decays over eight
tokens; a smaller 100-token term models the weak later response. Each
readable token class has fitted curve coefficients. The first token is
predicted as zero, and document changes reset the token count.

The newline after an initial user/assistant chat header has a stronger,
role-specific response. Individual words and richer context are omitted.
"""
import math

READS = ()

CONJUNCTIONS = {'and', 'or', 'but', 'nor', 'yet'}
COPULAS = {'is', 'are', 'was', 'were', 'be', 'been', 'being', 'am'}
GLUE_WORDS = {
    'i', 'you', 'he', 'she', 'it', 'we', 'they', 'my', 'your',
    'his', 'her', 'our', 'their', 'of', 'to', 'in', 'on', 'at',
    'by', 'as', 'with', 'from', 'for', 'that', 'this', 'which',
    'who', 'what', 'not', 'have', 'has', 'had', 'can', 'will',
    'would', 'could', 'should', 'do', 'does', 'did', 'if',
}


def token_kind(s):
    if s == '<|endoftext|>':
        return 'document_marker'
    if s.startswith('<|'):
        return 'chat_marker'
    if not s.strip():
        if s in ('\n', '\r\n'):
            return 'line_break'
        if '\n' in s:
            return 'blank_lines'
        return 'space' if s == ' ' else 'indentation'
    if all(not c.isalnum() for c in s):
        if '\n' in s:
            return 'punctuation_line_end'
        p = s.strip()
        if p in {'.', ',', '，', '。', '、', '،'}:
            return 'stop_or_comma'
        if p in {':', ';', '：', '；', '?', '!', '？', '！'}:
            return 'clause_punctuation'
        if p in {'(', '[', '{', '（', '【'}:
            return 'opening_bracket'
        if p in {')', ']', '}', '）', '】'}:
            return 'closing_bracket'
        if set(p) <= set('=-–—'):
            return 'dash_or_equals'
        return 'other_punctuation'
    if s.strip().isnumeric():
        return 'number'
    word = s.strip().lower()
    if s.startswith(' '):
        if word == 'the':
            return 'definite_article'
        if word in {'a', 'an'}:
            return 'indefinite_article'
        if word in CONJUNCTIONS:
            return 'conjunction'
        if word in COPULAS:
            return 'copula'
        if word in GLUE_WORDS:
            return 'glue_word'
    return 'ordinary_text'

# Each curve: late level, eight-token pulse, 100-token settling term.
CURVES = {
    'blank_lines': (-0.0206, -1.8193, 0.1651),
    'chat_marker': (-0.1006, 0.1287, 0.1852),
    'clause_punctuation': (0.0004, -1.1226, 0.0469),
    'closing_bracket': (0.0143, -0.9027, -0.0175),
    'conjunction': (-0.0014, -0.7199, 0.0903),
    'copula': (-0.0127, -0.4232, 0.1018),
    'dash_or_equals': (-0.0006, -0.5974, 0.0587),
    'definite_article': (-0.0071, -0.5252, 0.1068),
    'document_marker': (0.0845, 0.9427, -0.3487),
    'glue_word': (-0.022, -0.2138, 0.1138),
    'indefinite_article': (-0.0232, -0.3991, 0.125),
    'indentation': (-0.0126, -0.2371, 0.096),
    'line_break': (0.0106, -2.9987, 0.0773),
    'number': (-0.002, -0.1213, 0.0301),
    'opening_bracket': (-0.0054, -0.6283, 0.0692),
    'ordinary_text': (-0.0133, -0.1084, 0.0628),
    'other_punctuation': (-0.0019, -0.3179, 0.0538),
    'punctuation_line_end': (0.015, -1.4613, 0.0049),
    'space': (0.0134, -0.7624, -0.0059),
    'stop_or_comma': (0.0267, -1.5235, -0.0487),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    age = 0 if carry is None or carry[0] != doc else carry[1] + 1
    kind = token_kind(prefix.token_strings[-1])
    level, pulse, settling = CURVES[kind]
    value = 0.0 if age == 0 else (
