    if age == 2 and prefix.token_strings[-3] == '<|im_start|>':
        if prefix.token_strings[-1] == '\n':
            role = prefix.token_strings[-2]
            if role == 'user':
                value = -2.675
            elif role == 'assistant':
                value = -3.034
    return (doc, age), float(value)

