def step(carry, prefix, upstream: Mapping):
    s = prefix.token_strings[-1]
    if not s:
        return None, 0.0
    if all(ch.isspace() for ch in s):
        return None, -0.011 if "\n" in s or "\r" in s else -0.004
    if all(unicodedata.category(ch)[0] in "PZ" for ch in s):
        chars = [ch for ch in s if not ch.isspace()]
        if not chars:
            return None, -0.004
        scores = {",": -0.015, ".": -0.013, ":": -0.013,
                  ";": -0.011, "-": -0.009, "(": -0.006,
                  ")": -0.006, "[": -0.007, "]": -0.007}
        return None, sum(scores.get(ch, -0.006) for ch in chars) / len(chars)
    if s == "<|endoftext|>":
        return None, -0.004
    return None, 0.0

