    if word == '是不是':
        return -0.90
    if word.startswith('是'):
        if word in {'是我', '是你', '是有', '是对', '是可以', '是中国'}:
            return -4.70
        # 'Is a/one kind', with a numeral and classifier fused together.
        if word.startswith(('是一个', '是一個', '是一种', '是一種',
                            '是一名', '是一项', '是一位')):
            return -2.65
        # 'Is what', 'is how much', and 'means/refers to'.
        if word.startswith(('是什么', '是什麼', '是多少', '是指')):
            return -2.20
        return -3.70
    # Personal-pronoun subjects: 'I/you/he/she/it am/is'.
    if word in {'我是', '你是', '他是', '她是', '它是', '那是'}:
        return -2.40
    if word.startswith(('这是', '這是')) or word in {'都是', '也是', '才是', '又是'}:
        return -1.55
    if word in {'要是', '若是', '总是', '總是', '而不是', '并不是', '无论是'}:
        return -0.50
    if word in {'还是', '還是', '可是', '真是', '或是', '算是', '很是'}:
        return -0.80
    return -1.12


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    same_doc = (len(prefix.token_ids) > 1 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    prev = prefix.token_strings[-2] if same_doc else ''
    p = prev.strip().lower()
    w = s.strip()
    value = FORMS.get(w, 0.0)
    if w in {'is', 'are', 'am'}:
        boundary = s[:1].isspace() or not prev or not prev[-1:].isalnum()
        if not boundary:
            value = -0.04  # A syllable inside a longer word is not a copula.
        elif w == 'is':
            if not same_doc:
                value = -0.41
            elif p == 'what':
                value = 0.06
            elif p in {'it', 'this', 'which'}:
                value = -0.45
            elif p in {'here', 'who', 'one'}:
                value = -0.58
        elif w == 'are':
            if p == 'what':
                value = -0.40
            elif p in {'which', 'these', 'here'}:
                value = -0.79
        elif p != 'i':
            value = -0.16
    elif w in {"'s", '’s'}:
        value = {'what': 0.34, 'it': 0.19, 'he': 0.13,
                 'she': 0.13, 'that': 0.08, 'there': 0.08}.get(p, 0.02)
    elif w in {"'t", '’t'}:
        value = {'isn': -0.15, 'aren': -0.38,
                 'wasn': -0.16, 'weren': -0.29}.get(p, 0.0)
    elif s == ' be':
        if p in {'can', 'cannot', 'only', 'will', 'could', 'shall'}:
            value = 0.12
        elif p in {'may', 'might'}:
            value = -0.12
    elif w == 'been' and p == 'had':
        value = 0.38
    elif w == 'was':
        value = {'what': 0.56, 'this': 0.35, 'which': 0.22,
                 'who': 0.22, 'i': -0.05}.get(p, 0.08)
    elif '是' in w:
        value = chinese(w)
        if w == '是' and prev in {'，', '、', '。', '：'}:
            value = -3.13
    elif w in {'では', 'には', 'からは', 'としては', '時には'}:
        value = -0.24
    elif w.endswith('は') and w not in FORMS:
        value = 0.12 if w == 'または' else -0.47
    elif w.lstrip('._/(—-') in {'is', 'Is'}:
        value = -0.55  # Copula spelling used as a code identifier.
    elif w in {'isinstance', 'instanceof'}:
        value = -0.63
    return None, float(value)

programs.luna:
"""Approximate the component's negative response to copula words.

Its strongest sampled responses are to standalone English 'is' and 'are'.
A few sampled Chinese forms of 'be' and the Japanese topic particle are
also negative. Requiring a space before English words avoids treating a
word ending such as the 'is' in 'Paris' as a copula.
"""
READS = ()

_ENGLISH = {"is": -0.68, "are": -0.97, "Is": -0.37}
_CHINESE = {"是": -2.8, "是在": -3.4, "是一個": -2.4}
_JAPANESE = {"は": -0.76}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    if raw[:1].isspace():
        value = _ENGLISH.get(word, 0.0)
    else:
        value = _CHINESE.get(word, _JAPANESE.get(word, 0.0))
    return None, value
